/* Yoopanese display strings for the Cozy War ladder (323 tiers), keyed by the exact
 * English label in COZY_WAR_TIERS. Display-only: scoring always uses the English tiers. */
window.YOOPER = window.YOOPER || {};
window.YOOPER.COZY_WAR_TIERS = Object.assign(window.YOOPER.COZY_WAR_TIERS || {}, {
 "Sent Outside": {
  "label": "Sent Outside, Eh",
  "desc": "No rain, so no excuse, eh. At 10:04 a parent announces it’s a beautiful day, an’ both kids on da couch get sent outside for at least 45 minutes. Da blanket gets folded, da 4 cushions go back on da sofa, an’ da war’s called postponed, not lost. It’s 72°F an’ nobody’s happy about it."
 },
 "Sketch of a Fluffer": {
  "label": "Sketch of a Fluffer, Eh",
  "desc": "Dere’s no rain, so nobody gets to lie on da couch long enough to flatten anyting, an’ da war gets fought on paper instead. A machine gets drawn at 4 squares to da inch: 1 roller, 1 crank, a tray, an’ an arrow labeled “flat goes in here.” Nuttin’ has measurements on it an’ da crank’s drawn on da side facin’ da wall. It’s da first entry in a design record dat’ll run, by da household’s own count, some 40,000 years, ya know."
 },
 "Wet Grass Claim": {
  "label": "Da Wet Grass Claim",
  "desc": "At 7:15 da lawn’s wet, an’ da younger one, age 7, files a claim dat it rained overnight. Da claim gets looked at by da back door an’ denied, ’cause dew isn’t weather. One sock’s soaked right through to da second toe an’ goes into evidence. Da appeal gets heard after breakfast an’ takes under 2 minutes."
 },
 "Fluffer Dimensions": {
  "label": "Da Fluffer Gets Numbers",
  "desc": "Da sketch gets numbers: a 14-inch roller, 3 inches across, wrapped in felt an’ set over a slatted bed wit’ a 2-inch gap, so a 5-inch cushion gets squeezed to less dan half an’ let go. Da crank’s 3:1, 3 turns of da handle to 1 of da roller, an’ da drawin’ says 9 passes bring a cushion back to full loft. Measured rain’s at 0.00114 inches, which is to say none. Da drawin’ gets checked twice an’ it all adds up, which is more dan ya can say for da weather, eh."
 },
 "Porch Inspection": {
  "label": "Porch Inspection, Eh",
  "desc": "At 9:30 da younger one inspects da porch railin’ an’ finds 11 droplets, none of ’em fallin’. A report gets drafted in crayon sayin’ droplets are just rain dat quit. Da report’s 1 page long an’ spells droplets 3 different ways. It gets filed under da couch."
 },
 "Crank Ratio Argument": {
  "label": "Da Crank Ratio Argument",
  "desc": "Two people spend a whole afternoon arguin’ if da crank oughta be 3:1 or 5:1. Da 3:1 wins, ’cause a 7-year-old already gets about 40 turns a minute an’ nobody can crank faster to prove udderwise. Da argument gets settled wit’out a single cushion: rain’s at 0.0013 inches an’ neider one of ’em goes to da window to check, eh."
 },
 "Gauge Film": {
  "label": "Film in da Gauge",
  "desc": "Rain gets to 0.00139 inches, enough to leave a film in da bottom of da 6-inch plastic gauge on da deck post an’ not enough to feel on yer open hand. Both kids, 7 an’ 11, read it an’ agree to widin 10 percent, which is da best proof of rain eider one’s gonna get dis week. A parent looks at da gauge for 2 seconds an’ rules nobody stays inside for a film, eh."
 },
 "Shoebox Mock-Up": {
  "label": "Da Shoebox Mock-Up",
  "desc": "A full-size shell gets built outta a shoebox an’ 2 paper-towel tubes to prove da machine fits on da coffee table by da remote. It does, at 18 by 10 by 8 inches, leavin’ 4 inches for da remote, which was da whole point. It can’t fluff nuttin’, holds no cushion, an’ gets flattened in under 1 minute when da dog lies down on it, holy wah."
 },
 "Cushion Audit": {
  "label": "Da Cushion Audit",
  "desc": "Da couch gets a formal inventory: 2 seat cushions, 2 back cushions, an’ 2 throw pillows, 6 pieces all togedder, every one measured to da quarter inch. On paper dey make a fort; at 0.00159 inches of rain, every fort ya can figure comes out to zero, ’cause all 6 are still on da couch. Da inventory gets stuck on da TV screen an’ pulled down by a parent at 11:05, an’ both kids write dat down as da first censorship of da whole war."
 },
 "Gears and Clutch Drawn": {
  "label": "Gears an’ Clutch Drawn Up",
  "desc": "Da drive gets figured out end to end: a 12-tooth pinion on da crank, a 36-tooth gear on da roller, an’ a slip clutch in between set to let go da second a cushion quits gettin’ fuller an’ starts gettin’ thinner. It’ll let go before it can pinch a finger too, which is da part da parents read. Every number’s borrowed outta a catalog an’ none of ’em been tested. Rain’s at 0.00169 inches, so da clutch got nuttin’ to protect nobody from yet."
 },
 "Last April’s Fort": {
  "label": "Da Fort from Last April",
  "desc": "Da older one, 11, tells all about da fort from last April. Da story’s real detailed — 3 rooms, 9 cushions, a door dat worked, a 4-hour occupation — an’ not one bit of it can be checked. Four witnesses were s’posedly dere an’ 2 of ’em, da dog included, won’t back it up. Measured rain’s at 0.0018 inches, eh."
 },
 "First Printed Roller": {
  "label": "Da First Printed Roller",
  "desc": "Nine hours on a borrowed printer makes a roller core in 2 half-shells, split down da middle ’cause nobody could figure how else to print a tube 14 inches long. Da halves get glued, da seam sticks up half a millimeter da whole way along, an’ da felt goes over it anyhow. It turns in yer hand. Nuttin’ in da house is flat enough to feed it: at 0.00193 inches of rain, nobody’s been let to sit still long enough to flatten anyting."
 },
 "The Cousin’s Rain Day": {
  "label": "Da Cousin’s Rain Day",
  "desc": "Somebody says a cousin 3 towns over got to stay inside all day on account of rain an’ built a fort wit’ 12 cushions. It don’t work again across about 40 more appeals to a parent, dere’s no picture, an’ da cousin can’t be reached before 6:00. Da claim gets logged, argued over, an’ left hangin’, wit’ rain at 0.00206 inches, ya know."
 },
 "Roller Gap Check": {
  "label": "Checkin’ da Roller Gap",
  "desc": "Da roller goes into its frame an’ da gap to da slatted bed gets measured at 8 spots wit’ a ruler. Da target was 2 inches; da readings run 1.75 to 2.5, wit’ dat seam snaggin’ da felt at da same spot every turn. It gets sanded down by hand for about 40 minutes. Dere’s still no rain worth talkin’ about, an’ da check gets written down as passed, eh."
 },
 "Disputed Drop": {
  "label": "Da Disputed Drop",
  "desc": "One drop lands on da car windshield at 9:12, or else da sprinkler next door went off, dependin’ on which kid ya ask. Da 2 stories don’t match on one single ting: da size, da time, if it came from da sky or da gutter. Rain’s at 0.00235 inches, enough for a dark spot on a sleeve an’ not enough to keep nobody inside. Da house splits 2 to 2 an’ da dog stays out of it."
 },
 "Bathroom-Scale Clutch Test": {
  "label": "Clutch on da Bathroom Scale",
  "desc": "Da slip clutch gets loaded wit’ a bathroom scale an’ a wooden spoon till it lets go, 31 times in a row, at a force dat changes under 8 percent from one try to da next. It’s da first number in da whole project dat got measured instead of just picked. Rain on da patio: 0.00251 inches, an’ none of it’s gonna keep nobody on da couch long enough to flatten it, eh."
 },
 "Window Fog": {
  "label": "Window Fog, Eh",
  "desc": "Mist shows up an’ fogs da bottom 8 inches of da livin’ room window. Da younger one writes RAIN in it wit’ one finger, letters 3 inches tall, for da record. Da older one, age 11, looks it over from da doorway an’ concedes nuttin’. Da fog’s gone by 10:20 an’ da word goes wit’ it."
 },
 "Dry Crank, No Cushion": {
  "label": "Dry Crank, No Cushion, Eh",
  "desc": "Da whole machine gets set on da kitchen table an’ cranked 11 times wit’ nuttin’ in it, to check dat 3 turns of da handle give 1 of da roller an’ dat da clutch don’t slip wit’ no load. Both hold up. Da only ting comin’ out is a little tickin’ from da pinion, an’ da operator gets told 2 times to go do it in da garage."
 },
 "Damp Driveway": {
  "label": "Da Damp Driveway",
  "desc": "Ya can see it from da window across da whole driveway, but ya can’t see it from arm’s length. Rain of 0.00306 inches darkens da concrete for about 1 minute before it dries back in patches. Da two kids press der hands on it a full 30 seconds an’ come up wit’ nuttin’ a parent’s gonna call wet, eh."
 },
 "Bread Trial": {
  "label": "Da Bread Trial",
  "desc": "Testin’ starts inside wit’ da only squishy stuff nobody’s gonna miss. Six slices of sandwich bread, sat flat by a 7-year-old, go through da roller 9 passes each an’ come back to about 80 percent of how tall dey were. Da machine works, yah. Da felt’s full of crumbs for 2 days an’ dat trial never happens again."
 },
 "One Cushion": {
  "label": "One Cushion, Yah",
  "desc": "One sofa cushion, 24 by 24 by 5 inches, comes off da couch an’ goes on da floor as a forward position. It holds one kid an’ one stuffed bear. A parent points out it isn’t rainin’ an’ puts da cushion back at 8:02. It comes off again at 8:03."
 },
 "Sponge Calibration": {
  "label": "Sponge Calibration, Eh",
  "desc": "Kitchen sponges take over from da bread ’cause ya can rinse ’em off. Runs at every gap settin’ — 1 inch, 2, an’ 3 — bring squished sponges back to 95, 88, an’ 61 percent of full height in 9 passes, a nice clean curve. Da gap’s proven to knead an’ not just squeeze. Outside rain dat week adds up to 0.00372 inches an’ got nuttin’ to do wit’ it."
 },
 "Two Throw Pillows": {
  "label": "Two Trow Pillows",
  "desc": "Rain of 0.00397 inches gets ya da 2 throw pillows, 16 by 16 inches, an’ nuttin’ else. Strippin’ every chair, da window seat, an’ da dog bed brings it up to 4 soft tings, which takes 20 minutes an’ 1 argument wit’ da dog. Each one holds togedder for about 6 feet of flight, eh."
 },
 "Dog Bed Run": {
  "label": "Da Dog Bed Run",
  "desc": "Da dog’s bed, 30 by 40 inches an’ 6 pounds, tests da machine on somethin’ wit’ real heft: 9 passes in one afternoon wit’out a jam, but da felt slips on da nylon cover about 1 turn in 6. Slip gets written down as da weakest spot in da design an’ nobody fixes it. Everybody agrees a dog bed’s nuttin’ like a sofa cushion, an’ nobody dere has fluffed one of dose yet. Da dog lies down on it right away an’ undoes all 9 passes, holy wah."
 },
 "Sock Munitions": {
  "label": "Sock Munitions, Yah",
  "desc": "Ammo gets found. A laundry basket in da hall’s got 14 balled-up pairs of socks at about 2 ounces each, heavy enough to let ya know ya got hit an’ too light to do any harm. Every pair’s technically folded laundry, an’ da 2 dat get test-thrown come unballed widin 2 feet of lettin’ go. Nobody fires again."
 },
 "Sponge-Loaded": {
  "label": "Loaded Up wit’ Sponges",
  "desc": "Somebody sets up da Fluffer wit’ nuttin’ flat to put in it, so it gets loaded wit’ kitchen sponges — da same test stuff it got proven on 2 weeks back. Da gap goes to da widest stop an’ 11 sponges come out full height in a perfect row across 4 feet of coffee table. Everybody dere agrees dat’s not a fort. It goes in da record anyhow, ’cause da machine worked perfect an’ somebody oughta say so, eh."
 },
 "Gap Detents Set": {
  "label": "Gap Stops Set",
  "desc": "After da sponge run da gap gets 4 hard stops instead of a slidin’ wing nut: closed, 1 inch for throw pillows, 2 inches for seat cushions, 3 inches for sponges an’ da dog bed. Every stop gets checked by runnin’ 3 cushions through an’ measurin’ how dey bounce back wit’ a ruler. Over 10 runs it holds widin 9 percent, which is better dan da rain it was built for ever managed, ya know."
 },
 "Odd Sock Bin": {
  "label": "Da Odd Sock Bin",
  "desc": "Da odd-sock bin gets dumped on da rug: 11 singles wit’ no partner, gathered up instead of balled. Each one gets knotted into a round about 2 inches across, mostly toe. Ten can get made ready in 20 minutes, an’ about 2 in 3 come untied when ya let go. Rain’s at 0.00552 inches, eh."
 },
 "Felt Glazing Failure": {
  "label": "Da Felt Glazes Over",
  "desc": "Da first honest failure, on 0.00589 inches of rain. On da microfiber recliner cushion da felt glazes over an’ da roller spins wit’out grabbin’, an’ loft comes back to just 33 percent of da bench number in da same 9 passes. Nuttin’ breaks, which is da design doin’ what it’s s’posed to: a slippin’ roller does a lousy job instead of tearin’ a seam. Da whole ting gets written up, even da part where it didn’t work."
 },
 "Official Rain": {
  "label": "Official Rain, Eh",
  "desc": "Da first real drops hit da patio at about 1 per square foot per minute. Both kids watch from da slidin’ door, an’ da older one, 11, officially admits it’s rainin’. Inside war gets authorized at 1:12, but at 0.00629 inches it’s good for about 2 throws each before a parent says da rain isn’t dat heavy."
 },
 "Corduroy Rib Retrofit": {
  "label": "Corduroy Ribs Put On",
  "desc": "Raised ribs get glued along da roller over da felt, 8 of ’em, on da idea dat a roller dat can’t glaze can’t slip. Grip comes back to about 80 percent of da bench number on da same microfiber cushion, at 0.00672 inches of rain. Da cushions come out wit’ a ribbed pattern now, an’ 4 different people tink da dog slept on ’em."
 },
 "Half a Lean-To": {
  "label": "Half a Lean-To, Eh",
  "desc": "Just short of da stuff for one whole structure. Da Blanket’s still on da recliner an’ only 1 cushion’s allowed, so da lean-to’s a bath towel held up on 1 side by da cushion an’ on da udder by a 7-year-old’s arm. It holds about 40 seconds an’ comes down at da seam about half da time. Rain’s at 0.00717 inches."
 },
 "First Cushion Contact": {
  "label": "First Real Cushion",
  "desc": "Da machine meets a cushion dat’s actually flat for da first time: da left seat cushion, da one a parent reads on, pressed from 5 inches to 3.5 by 3 years of evenin’s. Nine passes bring it back to 5 inches. It’s a fresh cushion on an old couch, no doubt about it, an’ it lasts 4 minutes, till da parent sits back down. Pictures get taken from down low so da flat cushion next to it don’t show, eh."
 },
 "One Bad Sock": {
  "label": "One Bad Sock, Eh",
  "desc": "One single round: 1 sock balled up bad around a hair tie an’ some lint. It gets thrown once from maybe 9 feet, it misses, an’ it ends up under da couch where nobody can reach it. Da whole fight lasts under 10 seconds wit’ 1 kid on each side."
 },
 "Jammed Fluffer": {
  "label": "Da Fluffer Jams Up",
  "desc": "Da house’s one Fluffer grabs a crayon hidin’ in a cushion zipper, an’ da slip clutch does just what it was built for: da crank keeps turnin’, nuttin’ tears, an’ no loft comes out da back. Clearin’ it takes 40 seconds wit’ da felt guard lifted. Durin’ dose 40 seconds da operator can’t fight back, gets hit by 2 socks, an’ files da season’s first formal complaint about equipment, eh."
 },
 "Clutch Slips on Cue": {
  "label": "Da Clutch Slips Right on Cue",
  "desc": "A second jam, dis time da TV remote down da side of a cushion, an’ da clutch lets go before da operator notices anyting but a different sound. Da whole hold-up’s 9 seconds. Da bathroom-scale number holds widin 11 percent on a real cushion, which retires da last untested number in da machine. It’s da only equipment in da house dat’s never broke, not like da remote, which has 2 cracked buttons now."
 },
 "The Blanket": {
  "label": "Da Blanket",
  "desc": "Da Blanket gets issued: a 50-by-60-inch green fleece throw wit’ one corner chewed by da dog, 3 years on da back of da recliner. Dere’s exactly 1 in da house, both sides know where it is, an’ it changes hands 2 times before anybody sits under it. Draped over 1 cushion it makes a lean-to wit’ 2 square feet of floor space. Da dog, who chewed dat corner, doesn’t get asked."
 },
 "Full Loft in Nine": {
  "label": "Full Loft in Nine, Yah",
  "desc": "Da spec gets met for da first time: 9 passes bring a seat cushion back to a full 5 inches, checked wit’ a ruler at 10 spots, 17 percent variation. From 4 feet away da couch looks brand new. From da side it looks like a ramp, da cushion 1 inch higher in back, an’ da operator spends da next 20 minutes feedin’ it through front-first to fix dat."
 },
 "First Volley": {
  "label": "Da First Volley",
  "desc": "At 11:40 da laundry gets declared unfolded, an’ supply’s exactly 1 balled pair of socks apiece. Both get thrown in da same second from 9 feet, 1 hits, right in da shoulder, an’ da basket’s left empty. Zero casualties. A parent gives da both of ’em 10 minutes of refoldin’, an’ it takes ’em 22."
 },
 "Widening Wings": {
  "label": "Da Widenin’ Wings",
  "desc": "Da fold-out widenin’ wings get used for real da first time: 2 felt-lined guides dat tuck da edges of a 24-inch cushion into da 14-inch roller mouth. How long ya can go stops dependin’ on how wide da cushion is an’ starts dependin’ on da couch, which is da whole point. One session does all 4 seat an’ back cushions wit’out stoppin’, eh."
 },
 "Seven and Seven": {
  "label": "Seven an’ Seven",
  "desc": "Da sock basket gets split 7 an’ 7, an’ each side’s pile fits in one pair of cupped hands. Fire gets rationed right off at 2 socks a minute an’ it’s all gone widin 90 seconds of da first exchange. Two kids, no fixed spots, an’ no resupply till da next load comes outta da dryer."
 },
 "Flywheel Proof": {
  "label": "Provin’ da Flywheel",
  "desc": "A 2-pound flywheel gets bolted on da crank shaft an’ tested against a 7-year-old crankin’ in stop-start bursts on purpose. Loft variation wit’ da flywheel on runs 14 percent against 29 wit’ it off, over 3 matched runs. One part’s doin’ 2 jobs — smoothin’ out a choppy arm an’ holdin’ da machine down on da coffee table — an’ it’s da last piece of da design nobody proved yet."
 },
 "Pillowcase Sling": {
  "label": "Da Pillowcase Sling",
  "desc": "Da first try at a launcher: a balled sock dropped in an empty pillowcase, swung twice over yer head, an’ let go by feel. It goes 18 feet against a hand throw’s 9, an’ about 1 in 9 lands widin 3 feet of whatever ya aimed at. Two socks end up on top of da bookcase in da first hour, eh."
 },
 "Carpet Beater Prototype": {
  "label": "Da Carpet Beater Prototype",
  "desc": "Da older one brings out da rejected design: a wire carpet beater on a spring arm, worked wit’ one hand while da udder holds up a 20-by-26-inch pillow. It beats da pillow in a decent rhythm for about 30 seconds, an’ den da holdin’ arm gives out. Two get built an’ neider one makes it through da afternoon in one piece. Da crank-an’-roller gets agreed, once again an’ for da record, to be da right design, yah."
 },
 "The Beater Is Abandoned": {
  "label": "Da Beater Gets Dropped",
  "desc": "Both carpet beaters get stripped for parts widin 1 hour of failin’, an’ da decision goes in da record wit’ a reason, not just a verdict: a machine dat wants a holdin’ arm an’ a beatin’ arm at da same time has 1 arm too few. Da crank-an’-roller stands unchallenged from here on out. Da beaters’ 2 handles get kept an’ used, over da next 3 weeks, for fishin’ socks out from under da couch."
 },
 "Hoodie Pocket Arsenal": {
  "label": "Da Hoodie Pocket Arsenal",
  "desc": "Between 10 an’ 12 balled socks, carried in a hoodie front pocket ’cause dere’s nowhere else to put ’em. Good range gets to 12 feet an’ da hit rate runs about 1 in 5. Both sides start wit’ full supply an’ it’s settled widin 2 minutes by whoever throws slower, eh."
 },
 "Continuous Couch Feed": {
  "label": "Feedin’ Straight off da Couch",
  "desc": "Da main mode goes operational: park da Fluffer at da end of da couch, feed cushions in one after da udder, an’ never lift a cushion higher dan da armrest. All 6 pieces from da inventory get fixed up in one long session of about 6 minutes, wit’ rain at 0.0192 inches. Loft stops dependin’ on how long ago da couch got bought an’ starts dependin’ on who’s willin’ to crank."
 },
 "Pillow Skirmish": {
  "label": "Pillow Skirmish, Eh",
  "desc": "Real pillows, for a little bit: both regular pillows, 20 by 26 inches, 1 per side, plus 1 throw pillow each. Seventeen hits go back an’ forth in about 90 seconds, both sides run outta breath before anybody gets cover, an’ it ends ’cause everybody’s pooped, not ’cause anybody won. Losses get written down as 2 bruised egos an’ a lamp dat wobbled but stayed up."
 },
 "Salad Tong Launcher": {
  "label": "Da Salad Tong Launcher",
  "desc": "A pair of salad tongs turns out to hold a balled sock an’ fling it wit’out it comin’ apart. Range runs 14 feet, da sock stays in one piece 9 times outta 10, an’ one person can load an’ throw wit’out settin’ nuttin’ down. It turns into da standard tool for da 7-year-old an’ anybody else who can’t throw hard."
 },
 "Second Fluffer Built": {
  "label": "Second Fluffer Built, Eh",
  "desc": "A second machine gets printed off da same files over 2 nights, wit’ da roller seam fixed in da model instead of sanded off by hand. Da 2 are widin 4 percent of each udder on loft put back per pass, so da design’s repeatable an’ not just lucky. From here on dere’s a fleet, of 2."
 },
 "Hallway Flank": {
  "label": "Flankin’ Down da Hallway",
  "desc": "Supply gets to about 18 socks a side, enough dat one kid can break off an’ circle around wit’out leavin’ da line empty. Da first sneaky approach of da war runs from da couch through da kitchen an’ back down da hallway, 40 feet in 11 seconds, da runner carryin’ 5 socks an’ gettin’ to 6 feet before anybody looks. It works once, an’ both sides put a lookout at da kitchen door from den on."
 },
 "Tube Sock Sling": {
  "label": "Da Tube Sock Sling",
  "desc": "A tube sock wit’ a balled sock in da toe, swung underhand an’ let go at da bottom of da swing. It gets 25 feet at full stretch, but good range stays around 12 ’cause 1 throw in 8 lands anywhere near where ya meant. Da older one gets hit by der own throw 4 times da first afternoon, an’ it stays in service anyhow."
 },
 "Recliner Ambush": {
  "label": "Ambush Behind da Recliner",
  "desc": "Enough supply to crouch behind da recliner wit’ 3 socks in reserve an’ 15 all togedder. Where ya sit starts to matter, an’ holdin’ yer fire’s an option now, but 2 tries in 3 get given away by da dog, an’ openin’ range drops under 5 feet. Fights run 3 to 5 minutes an’ come down to who’s got more left when da first volley’s done, eh."
 },
 "Fluffer on Loan": {
  "label": "Da Fluffer on Loan",
  "desc": "A Fluffer leaves da house for da first time, lent to a family 4 doors down so long as it comes back da same day. It does, 3 hours late, wit’ dog hair in da felt an’ a wing hinge sprung. Four more households ask for one dat week an’ get told dere’s only 2 in da whole world, eh."
 },
 "Sock Standoff": {
  "label": "Da Sock Standoff",
  "desc": "Both kids got 10 balled-up pairs of socks apiece, an’ neider one’s gonna throw first, eh. Da pause runs 4 to 6 minutes across 16 feet of livin’ room carpet, wit’ about 1 probin’ toss a minute, none of ’em aimed at nuttin’ but da floor. It ends at 10:00 when da neighbor kid, age 9, shows up under an umbrella wit’ a sleepin’ bag an’ picks da side wit’ da flashlight."
 },
 "Basket Volley": {
  "label": "Da Basket Volley",
  "desc": "Da laundry basket gets swung to throw 4 socks at once instead of 1 sock farther, ya know. Nuttin’ goes past 12 feet an’ nuttin’s aimed, but da spread covers da whole 7-foot front of da couch, da first time in da war an area gets attacked instead of a sibling. Reloadin’ takes 11 seconds against 2 for a hand throw, an’ da basket handle cracks on da 9th swing."
 },
 "Two-Fluffer Line": {
  "label": "Two-Fluffer Line, Eh",
  "desc": "Both Fluffers get run across da couch in an overlappin’ line, da second guy crankin’ half a roller’s width behind da first, an’ dat gets rid of da ridge one 14-inch pass leaves down da middle of a 24-inch seat cushion. Every cushion comes back to full loft in 9 passes wit’ no seam at all. Callin’ out da offset by voice flops right away, so da second guy just watches da first one’s crank handle instead."
 },
 "Pillow Duel": {
  "label": "Da Pillow Duel",
  "desc": "Two serious siblings, 2 regular pillows apiece, an’ a crowd of 5 stuffed animals an’ da dog, eh. Rules get set ahead of time for range, what ya can hit, an’ how many swings a side, an’ faces get ruled out by a unanimous vote of 2. First to 5 confirmed hits wins it, an’ da whole deal runs 8 to 12 minutes countin’ 1 break to re-tuck a pillowcase."
 },
 "Loft Contest": {
  "label": "Da Loft Contest",
  "desc": "Da first time anybody competes wit’ ’em: 2 operators, 2 Fluffers, 20 minutes, most cushions brought back to believable loft. Da winner does 19 cushions an’ gets disqualified for a throw pillow dat got 4 passes instead of 9, which still shows a sit-dent from da doorway, holy wah. Da rule dat a cushion’s gotta look like nobody sat on it from da kitchen doorway at suppertime goes in da record an’ never comes out."
 },
 "Party Moved Indoors": {
  "label": "Da Party Moved Inside",
  "desc": "Drizzle moves a 9th birthday party inside, an’ 8 guests find da throw pillows. Dere’s no teams an’ about 25 rounds a kid, countin’ socks, pillows, an’ 1 blow-up crown. Alliances last under 30 seconds an’ average 4 a kid over da whole deal. It runs 15 minutes, nobody agrees who won, an’ it ends when da last sock goes under da couch, 2 minutes before da cake."
 },
 "Fluffer Rivalry": {
  "label": "Da Fluffer Rivalry",
  "desc": "Both sides of da fight each get a Fluffer, an’ da war gets a second front, fought over cushions instead of wit’ ’em. Neider operator throws nuttin’ all afternoon. Each one cranks about 40 cushions back to full loft at 9 passes apiece, more den deir whole side threw in 3 hours, an’ both get told at supper dey missed da actual battle, eh."
 },
 "Proper Pillow Fight": {
  "label": "A Real Pillow Fight, Yah",
  "desc": "A real fight finally: 6 to 10 kids from 3 houses, cover behind da sofa an’ 2 armchairs, an’ a pile dat keeps gettin’ restocked from da dryer at about 40 rounds a side. Good range gets out to 20 feet, da length of da livin’ room. How long it lasts depends on how long it takes a parent to come downstairs, which is usually 20 to 30 minutes, ya know."
 },
 "Fluffer Patent Dispute": {
  "label": "Da Fluffer Patent Fight",
  "desc": "Two households both say da machine’s deir design: a 14-inch felt-covered roller, a 3:1 crank, an’ a slip clutch set to let go below da grip of a 7-year-old. Da case gets heard in a garage by 3 older kids, an’ da original goes in as evidence: graph paper at 4 squares to da inch, an arrow labeled “flat goes in here,” dated in felt-tip in da corner. Da panel rules for da kid who drew it an’ lets da udder household build from da drawin’, so long as every roller’s got a stitched mark givin’ credit for da design."
 },
 "Counterfeit Fluffers": {
  "label": "Phony Fluffers, Eh",
  "desc": "Machines start showin’ up dat weren’t built from da drawin’: bare wood rollers, a 1:1 crank, no clutch at all. Tree of da 4 quit inside a week, 2 of ’em by rippin’ a cushion seam under load, exactly da way da clutch is dere to stop. Da original design gets a stitched red mark on da roller’s end cap to tell it apart, an’ da mark gets copied inside 9 days, holy wah."
 },
 "Room-to-Room": {
  "label": "Room to Room, Yah",
  "desc": "Da fight quits holdin’ still an’ moves trew da livin’ room, da hallway, da kitchen, an’ up 14 stairs, coverin’ about 90 feet in half an hour. Socks get balled up on da run at about 1 every 15 seconds. Neider side holds a room more den 90 seconds, an’ da whole supply never gets past 50, ya know."
 },
 "Sewn in a Basement": {
  "label": "Sewed in da Basement",
  "desc": "Production moves down to a sewin’ table in da basement, where a grandparent who never threw one sock in dis whole war stitches felt roller covers overnight, 2 sheets an’ 50 minutes a roller, 4 machines a week if da bobbin holds up. Da holdup quits bein’ da design an’ turns into felt, sold at da craft store in 9-by-12-inch sheets. Da grandparent ends up da most important person on da block an’ gets paid in cookies, 6 a roller, eh."
 },
 "Banister Slingshot": {
  "label": "Da Banister Slingshot",
  "desc": "A bungee cord gets stretched between 2 banister spindles on da landin’ an’ pulled back by a second kid layin’ flat on da carpet. A balled-up sock goes 40 feet, twice anyting thrown by hand, straight down da hall into da kitchen, an’ da slingshot can’t move once it’s tied. It comes down after 4 days when da near spindle pops out of da railin’, holy wah."
 },
 "Juice Box Intermission": {
  "label": "Juice Box Break, Eh",
  "desc": "Da ammo now outlasts da kids, wit’ each side holdin’ 80 or more rounds any time once ya count da dryer. Everybody’s red in da face an’ dried out around da 40-minute mark, da fightin’ stops 15 to 20 minutes for juice boxes at da kitchen table, an’ den it starts up again full strength wit’ 2 fewer pillowcases."
 },
 "Loft Doctrine": {
  "label": "Da Loft Doctrine",
  "desc": "A written standard shows up: 9 passes minimum, no crease ya can see, an’ no Fluffer on any cushion while somebody’s sittin’ on it. Da last of da 3 is da only one anybody enforces, an’ dey enforce it all da way, ya know. Two operators get benched for 1 week over one pass along da arm of da recliner while a parent was in it, an’ neider one argues."
 },
 "The Cushion Pile": {
  "label": "Da Cushion Pile",
  "desc": "Da first fort of any kind is just a heap, eh. Every cushion inside 20 feet gets pulled off da couch, 2 armchairs, an’ da window seat an’ piled on da carpet knee-high, about 16 inches, an’ 4 feet across. Two kids crouch behind it an’ nobody calls it a wall, ’cause it isn’t one. Da fort era starts wit’ 9 cushions an’ a heap."
 },
 "Sock Attrition": {
  "label": "Sock Attrition, Yah",
  "desc": "Neider side can get chased off an’ neider one can restock faster den it throws. Da sock baller at da dryer turns out 4 rounds a minute a side, but dey’re throwin’ 6. Fights now end when da laundry runs out after 70 to 90 minutes, wit’ hit counts in da low hundreds an’ da dryer lint trap full right up."
 },
 "Escorted Fluffers": {
  "label": "Escorted Fluffers, Eh",
  "desc": "A kid crankin’ a Fluffer at da end of da couch is a sittin’ duck, an’ both sides figure dat out da same afternoon. Operators get 2 sock throwers apiece whose only job is keepin’ da re-loftin’ goin’. Cushions done an hour drop by a third, from 30 to 20, but finished jobs go from under half to 9 in 10."
 },
 "Pitched Pillow Battle": {
  "label": "Da Pitched Pillow Battle",
  "desc": "Dere’s enough stuff for steady volleys from fixed spots at 6 to 8 throws a minute a side, half of ’em slung from a pillowcase wit’ a sock in da toe at 30 feet against 20 for a hand throw. Score gets kept, hits get called out loud, an’ da runnin’ count gets argued about every 3rd call or so. Fights go past 1 hour an’ pull in 8 to 14 kids from 4 houses, eh."
 },
 "Wall Refluff": {
  "label": "Da Wall Refluff",
  "desc": "Da Fluffers get turned on da forts demselves, givin’ 9 passes to wall cushions squashed flat by 3 days of use. It don’t add any stuffin’ an’ nuttin’ structural. It makes da whole works look brand-new built from 12 feet away, which is worth more den any stuffin’, an’ da habit sticks around for every later part of da war, ya know."
 },
 "Behind the Rolled Rug": {
  "label": "Behind da Rolled-Up Rug",
  "desc": "Spots get laid down in instead of built up: da 8-foot area rug gets rolled back into a log 10 inches high, an’ kids lay flat in da 20-inch gap between it an’ da baseboard, 12 feet long. It stops a low sock an’ nuttin’ else, an’ ya can’t swing a pillowcase from in dere. Two lines like dat face each udder at 15 feet an’ neider one gets left da rest of da afternoon."
 },
 "Fluffer Sabotage": {
  "label": "Fluffer Sabotage, Holy Wah",
  "desc": "A handful of dry cereal gets shoved into da intake of a Fluffer nobody’s watchin’ overnight. Da clutch does its job on da first turn of da crank an’ nuttin’ breaks, but 140 crumbs gotta get picked outta da felt by flashlight over 50 minutes, an’ da mornin’ re-loftin’ never happens. It’s da first attack in da war aimed at equipment instead of people, an’ it works better den 3 days of socks, eh."
 },
 "Cushion Wall": {
  "label": "Da Cushion Wall",
  "desc": "Da first built ting of da day: 4 seat cushions stood up on edge, knee-high at 18 to 24 inches, set up an’ set up again over about 40 minutes. It runs 8 feet long an’ 5 inches thick, enough to stop a straight sock from 15 feet out, but not a pillow lobbed over da top. One wall, one side, an’ nuttin’ facin’ it yet, ya know."
 },
 "Backpack Fluffer": {
  "label": "Da Backpack Fluffer",
  "desc": "Regular personal issue shows up: a 3-pound Fluffer wit’ a foldin’ crank dat fills most of a school backpack an’ still carries da full 14-inch roller. It don’t add stuffin’; it moves it, workin’ da flattened fillin’ of a beat-up cushion back out to da corners in 9 passes. One operator re-lofts 6 wall cushions in da time a sock baller balls up 4 pairs. Every wall crew puts in for one, eh."
 },
 "Wide-Body Fluffer": {
  "label": "Da Wide-Body Fluffer",
  "desc": "A bigger machine shows up wit’ a 28-inch roller an’ wheels off a rollin’ suitcase, re-loftin’ a whole couch seat in da time da regular one does half. It don’t fit any backpack an’ it takes 2 people to lift up da stairs. Da trade’s made right out in da open: carryin’ traded for width, on a design whose whole point was dat a 7-year-old could carry it, holy wah."
 },
 "Paddle and Noodle": {
  "label": "Paddle an’ Noodle",
  "desc": "Socks start gettin’ hit instead of thrown, wit’ a ping-pong paddle an’ a pool noodle swiped from da garage, neider one goin’ back before summer. A clean hit goes 30 feet, near double a hand throw, but 3 socks outta 5 come unballed when dey get smacked. Ballin’ gets tightened to a double tuck just so dey make it trew da swing, ya know."
 },
 "Couch-Arm Elbow": {
  "label": "Da Couch-Arm Elbow",
  "desc": "Da first L-shaped wall uses da couch arm for da return: 8 feet of stacked cushions across da front an’ 4 feet of sofa coverin’ da left side, 22 inches high. It’s da best spot in da house for about 10 minutes, eh. Da open right side is where every hit comes from now."
 },
 "Couch-Frame Moat": {
  "label": "Da Couch-Frame Moat",
  "desc": "Da cushions for da wall now come right off da couch, an’ da bare frame turns into da ditch: 84 inches of bare deck an’ springs any attacker’s gotta cross, so da wall’s good for 4 feet from da attackin’ side. Da whole works run 12 feet across an’ take 90 minutes. A straight charge has gotta climb over da springs, which adds about 4 seconds out in da open an’ 1 banged-up knee, holy wah."
 },
 "Three-Sided Fort": {
  "label": "Da Tree-Sided Fort",
  "desc": "Tree walls, open back: a front of 2 couch cushions plus 2 side walls of ottoman an’ laundry basket, about 6 by 4 feet inside an’ 2 feet high. Da open back faces da kitchen for restockin’. It’s da first fort da kids sit inside instead of behind, an’ 3 of ’em fit if 1 holds da dog, ya know."
 },
 "Fort-Building Rules": {
  "label": "Fort-Buildin’ Rules",
  "desc": "Walls go up for real at 30 inches high, stacked from every cushion in 3 houses, wit’ 16 feet of front an’ about 200 rounds piled up behind. Teams of 4 to 6 form up a side, an’ rules get hashed out for wall height, throwin’ range, snack breaks, an’ what ya can swing. Buildin’ runs 90 minutes before da first sock gets thrown, eh."
 },
 "Box Foxholes": {
  "label": "Box Foxholes, Yah",
  "desc": "One-kid spots show up in front of da forts: laundry baskets an’ movin’ boxes about 2 feet deep, each rim padded wit’ a folded towel. Every box gets claimed by 1 kid, who spends about 25 minutes findin’ it, emptyin’ it, an’ arguin’ over it. It’s da start of da box family, shallower den anyting dat comes later, an’ 4 are in use by noon."
 },
 "Fluffer Bay": {
  "label": "Da Fluffer Bay",
  "desc": "Forts start gettin’ built wit’ a covered bay in da back wall sized for a Fluffer wit’ da wings folded, 14 inches of roller an’ a 3:1 crank. Goin’ from a flat wall to a re-lofted one drops under 3 minutes ’cause nobody walks to da hall closet no more. Every fort plan drawn after dis has got da bay, even a bunch dat never get a Fluffer, eh."
 },
 "Four-Wall Fort": {
  "label": "Da Four-Wall Fort",
  "desc": "Four walls, all closed in: 8 cushions stood on edge around a 6-by-6-foot floor, 30 inches high, wit’ a crawl-trew gap in da back wall da width of 1 cushion. It’s da first fort wit’ no open side. Da corners are da weak spots, where 2 cushions meet at an angle an’ lean apart, an’ dey sag first, usually inside 20 minutes, ya know."
 },
 "Ottoman Redoubt": {
  "label": "Da Ottoman Redoubt",
  "desc": "A second, smaller spot gets built behind da main wall to fall back to: an ottoman an’ 2 throw pillows, 3 feet across an’ 30 inches high, holdin’ a reserve of 30 socks. It gets used twice in an afternoon an’ both times da main wall gets taken back inside 10 minutes. Da works on each side now run past 12 feet of front, eh."
 },
 "Fluffer Crews": {
  "label": "Fluffer Crews, Yah",
  "desc": "Runnin’ one quits bein’ a one-kid job: 3 to a machine, one crankin’, one feedin’ cushions to da roller an’ clearin’ da intake, one luggin’ da next cushion in. Steady output just about triples, to about 30 cushions an hour at 9 passes each. Da crew’s da first ting in da war set up around a piece of equipment instead of a fort or a friendship, ya know."
 },
 "Rival Forts": {
  "label": "Da Rival Forts",
  "desc": "Da udder side starts buildin’ across da livin’ room, 15 to 20 feet away. Both sides build da front wall full height, 3 feet or better, outta cushions, a twin mattress, an’ a coffee table tipped on its side, an’ both leave da sides open. All togedder it’s 4 kid-hours of work before anybody throws a ting, holy wah."
 },
 "The Round Fort": {
  "label": "Da Round Fort",
  "desc": "A round wall of 11 cushions stood on end, 6 feet across inside an’ 3 feet high, built ’cause da square fort’s corners kept saggin’: no corners, nuttin’ to cave in. Ya can throw just as good in every direction. It’s a lot harder to build even, dough, ’cause every cushion in da house is a rectangle, an’ da first 2 tries come out oval, eh."
 },
 "Contested Rug": {
  "label": "Da Fought-Over Rug",
  "desc": "Da 15 feet of rug between da forts changes hands 6 times in an afternoon. Neider side hangs onto it more den 11 minutes, an’ every try costs about 40 rounds an’ starts wit’ a bungee slingshot layin’ 12 of ’em across da front. Da piles togedder get past 300, countin’ every sock, foam ball, an’ beanbag on da street, an’ da dryer keeps up wit’ da throwin’ for da first time all day."
 },
 "Phantom Tidying": {
  "label": "Da Phantom Tidyin’",
  "desc": "An overnight run re-lofts all 14 cushions in da udder side’s livin’ room, an’ dey wake up sure a parent tidied up an’ nobody ever fought dere. Da trick holds most of a mornin’, about 3 hours, an’ falls apart on da roller marks: 14-inch stripes of fluffed-up nap runnin’ in perfect straight lines across da velour. After dat, both sides check for stripes before dey believe anybody cleaned anyting at all, holy wah."
 },
 "Bathtub Fort": {
  "label": "Da Bathtub Fort",
  "desc": "Da fort floor gets dug down by movin’ da whole ting into da dry bathtub, 15 inches deep, wit’ 3 cushions stood on da rim, so 24 inches of wall gives about 39 inches of cover. It’s a wall an’ a trench in 1 fixture, eh. Da faucet drips once every 9 seconds, an’ a puddle forms down by da drain dat nobody can sit in."
 },
 "The Sock Baller": {
  "label": "Da Sock Baller",
  "desc": "Walls get to 18 inches thick an’ 40 inches high, enough to take a straight pillow wit’out droppin’ a cushion, across 10 feet of front. A full-time sock baller gets picked an’ works nonstop at da dryer behind da line, turnin’ out 12 rounds a minute, 4 of which go to da pillowcase slingers every time. Da piles on each side get past 150, ya know."
 },
 "Fluffer Pickets": {
  "label": "Fluffer Pickets, Eh",
  "desc": "Fluffers get posted at da edges of da carpet ya hold to lay down an’ re-loft a strip of floor cushions, so anybody crossin’ leaves a dent. Dat turns da Fluffer from a supply machine into a lookout. A crossin’ gets caught dis way at 2 in da afternoon by one knee-print 4 inches deep, an’ da fight dat follows pulls in 11 kids an’ not one cushion dat wasn’t fluffed on purpose."
 },
 "Footstool Outworks": {
  "label": "Da Footstool Outworks",
  "desc": "Spots off on deir own get pushed 6 feet out in front of da main wall to break up anybody comin’: 2 a side, each a footstool wit’ a throw pillow propped on it, manned by 1 kid. Dey fall usually inside 4 minutes of a real push an’ get rebuilt at snack time. Da defended depth goes from 2 feet to about 10, which puts da main wall outta reach of a pillowcase sling, eh."
 },
 "Front Room, Back Room": {
  "label": "Front Room, Back Room, Yah",
  "desc": "Da first fort wit’ a wall inside: 2 rooms side by side split by a couch back cushion, wit’ a doorway hung from a dish towel. Da front room, 4 by 5 feet, is for throwin’. Da back room, 4 by 3 feet, holds da pile, 2 juice boxes, an’ whoever’s restin’, an’ ya only go in wit’ permission, ya know."
 },
 "Glacis Fluffing": {
  "label": "Da Glacis Fluffin’",
  "desc": "Da open carpet in front of da works gets covered on purpose wit’ floor cushions an’ da queen comforter, fluffed smooth an’ even before a siege so dere’s no cover an’ every knee-print shows. All 20 feet of da approach gets re-lofted at 9 passes a cushion in about 50 minutes. Da attackers come up along da one strip da wings couldn’t reach, a 2-foot gap behind da couch against da wall, holy wah."
 },
 "Siege of the Sofa": {
  "label": "Siege of da Sofa",
  "desc": "Neider fort can get taken by a straight charge no more; 3 tries over 2 hours all come up short of da wall. Pillowcase slings get pointed up instead, lobbin’ socks over da wall from 25 feet, da first throws da defenders can’t see comin’. Da standoff gets settled by who’s got da bigger pile, not by any one charge, an’ both sides hold over 200 rounds an’ make ’em faster den dey can throw ’em, eh."
 },
 "Armchair Bastions": {
  "label": "Da Armchair Bastions",
  "desc": "Da square fort gets bastions: an armchair at each of da 4 corners, turned 45 degrees out so every cushion wall gets covered by throws from da chair next to it. Dere’s no blind spot at da bottom of any wall, an’ a kid crawlin’ up to one gets seen from 2 sides at once. It’s da fort da siege was waitin’ for, an’ it takes 3 kids 50 minutes, ya know."
 },
 "Standing Siege": {
  "label": "Da Standin’ Siege",
  "desc": "Da siege turns into just how tings are instead of someting dat happens. Each fort holds 6 kids wit’ 3 more waitin’ on da stairs, an’ da rug between ’em sits empty for 40 minutes at a stretch. What da dryer makes an’ what da walls throw evens out around 150 rounds a side, an’ neider pile budges, eh."
 },
 "Draft-Snake Ring": {
  "label": "Da Draft-Snake Ring",
  "desc": "A line goes all da way around da udder fort wit’ no gaps: 40 feet of rolled-up towels, sleepin’ bags, an’ a queen blanket twisted into a draft snake 18 inches high, boxin’ it in completely. Buildin’ it takes 2 days an’ 9 kids, an’ da finished ring gets walked by 2 slingers goin’ opposite ways. Restockin’ da fort inside, cut off from da kitchen an’ da dryer both, drops to 0, an’ dey’re down to 40 socks, holy wah."
 },
 "The Fluffer Manual": {
  "label": "Da Fluffer Manual",
  "desc": "Everyting dey learned gets written down in 22 hand-numbered pages: pass counts by cushion type, da wing angle for a sofa arm, da 9-second clutch check, an’ da standin’ rule about cushions wit’ somebody on ’em. It gets copied by hand 4 times an’ every copy comes out different. Tree hundred years later, 4 copies still around disagree on da pass table an’ all of ’em cite da same lost original, written in purple marker on da back of a spellin’ test, eh."
 },
 "Cushion Battlements": {
  "label": "Cushion Battlements, Yah",
  "desc": "Walls get up to 4 to 5 feet, a twin mattress stood on edge behind da cushions, wit’ 4 throwin’ notches a side, each 10 inches wide, cut so a pillowcase sling clears on da let-go. A step-stool lookout sits 2 feet over da wall, so ya can see clear to da kitchen doorway at 30 feet, an’ da warnin’ when somebody’s comin’ goes from 3 seconds to 12. Each fort’s got 8 kids now, countin’ da dog."
 },
 "Night Fluffing": {
  "label": "Night Fluffin’",
  "desc": "Re-loftin’ moves to da dark ’cause a kid crankin’ at walkin’ speed can’t be defended in daylight. Da glow-in-da-dark tape on da crank handles, put on so nobody trips on a Fluffer goin’ to da bathroom an’ grumbled about ever since, turns out to be da only way crews find each udder. Output drops by a quarter, from 30 cushions an hour to about 22; equipment losses drop to 0, ya know."
 },
 "Sleepover Watch": {
  "label": "Da Sleepover Watch",
  "desc": "Spots get manned nonstop for da first time, in 2-hour shifts across 4 kids a fort all trew a sleepover night. Da watch runs from lights-out at 10:00 to da first cartoons, about 9 hours, wit’ a loaded pillowcase kept at every notch. Two night raids get tried by bunches of 3, both spotted inside 6 feet of da wall instead of 15 like in daylight, an’ both chased off inside 90 seconds, eh."
 },
 "First Roof": {
  "label": "Da First Roof",
  "desc": "Da first roof: every cushion in da room gets heaped 4 feet high around 2 kitchen chairs, da Blanket gets tossed over da top, an’ da whole ting gets left alone for 2 hours while everybody eats lunch. Den it gets hollowed out from da inside, cushions pulled out da door one at a time till dere’s a room left, 34 inches high at da chair backs, wit’ 6 clothespins holdin’ da fleece. It seats 3 kids, or 2 an’ da dog, holy wah."
 },
 "Fluffer Depots": {
  "label": "Fluffer Depots, Eh",
  "desc": "Da Fluffers quit belongin’ to kids an’ start belongin’ to forts. Each sleepover house keeps a numbered laundry basket of spares: felt sleeves for da 14-inch roller, slip-clutch springs, wing hinges, an’ 2 extra crank handles. Dere’s 12 Fluffers an’ 40 spare parts across 4 depots, one in each of 3 houses an’ one out in a garage. Time from a sprung wing hinge to a workin’ Fluffer back at da cushion line drops from a whole day to 11 minutes, eh."
 },
 "Three-Sleepover Campaign": {
  "label": "Da T’ree-Sleepover Campaign",
  "desc": "Da rain gets past an inch an’ 3 sleepovers are goin’ on da same block all at once, 400 feet of street an’ 30 kids between ’em. Alliances form up by who’s got da most marshmallows an’ harden da minute da first shared walkie-talkie channel gets picked, lastin’ about 9 hours apiece. No one house can hold out against da udder 2 togedder, an’ every house knows it by 8:00."
 },
 "Duvet Dome": {
  "label": "Da Duvet Dome",
  "desc": "Da first dome fort goes up in da biggest livin’ room: a king duvet over a ring of 6 dinin’ chairs, propped up in da middle on a 5-foot broom-handle pole, wit’ cushions laid round da hem in a risin’ spiral to pin it down. Inside it’s 7 feet across an’ 5 feet at da peak. Wit’ 4 kids in dere it runs 6 degrees warmer dan da room, yah. Da door’s a 4-foot sleepin’-bag tunnel, built low so da hallway draft stays out."
 },
 "Fluffer Repair Kit": {
  "label": "Fluffer Fix-It Kit",
  "desc": "A zipper pencil case goes out wit’ every Fluffer crew, holdin’ 2 clutch springs, a spare crank pinion, 4 felt sleeves for da 14-inch roller, an’ a pair of blunt scissors. About 90 percent of breakdowns get fixed right at da fort where dey happen now. Da most-used ting’s da scissors, for cuttin’ thread an’ dog hair outta da roller, an’ da least-used is da pinion, which nobody’s ever seen quit, ya know."
 },
 "Floor Works": {
  "label": "Da Floor Works",
  "desc": "Buildin’ spreads out past da forts onto da floor in between: ottoman steps, cushion ramps, an’ laundry-basket zigzags, 300 feet of fixed-up route across 3 houses. Two hallways get set up for a fitted-sheet sling worked by 2 kids, which t’rows a pillow 28 feet. Eleven kids work on it da whole afternoon. Every route to every fort crosses at least 1 built obstacle now, even da route to da bathroom, eh."
 },
 "Crawlway Fluffer": {
  "label": "Da Crawlway Fluffer",
  "desc": "A skinny Fluffer gets built for da crawlways, its roller cut down from 14 inches to 8 so it fits between cushion walls set 24 inches apart. It puffs back up da floor pads, couch cushions squashed flat by about 200 knee crossin’s a day. It don’t help da fightin’ one bit. It cuts da carpet burns in half, an’ a crawlway wit’ fewer carpet burns stays full for more hours, which is da whole argument for it, yah."
 },
 "Crawl Trenches": {
  "label": "Crawl Trenches, Eh",
  "desc": "Couch cushions get stood up on edge in 2 rows facin’ each udder between da forts, 24 inches high an’ 60 to 90 feet in total run t’rough da host house. Ya can move under cover now, an’ da fightin’ drops down below da cushion line for da first time, but ya lose da overhand pillow swing, ’cause ya can’t do dat on yer knees in a 2-foot corridor. Gettin’ from da livin’ room to da kitchen goes from an exposed 10 seconds to a covered 30."
 },
 "Supply Crawlway": {
  "label": "Da Supply Crawlway",
  "desc": "A special back crawlway hooks up every front fort to da sock basket in da laundry room, 120 feet of it under a 3-foot ceilin’ of dinin’ chairs an’ da queen sheet. Supply runs dat used to get shot at crossin’ da open kitchen now finish unseen in 40 seconds. How many socks ya can keep t’rowin’ at da front just about doubles, an’ so does da laundry, eh."
 },
 "Fluffer Sappers": {
  "label": "Da Fluffer Sappers",
  "desc": "Every new crawlway robs a couch, an’ a robbed couch gives itself away from da front door. Fluffer crews get stuck wit’ da builders to puff back up da cushions left behind, 9 passes apiece, so da sofa looks whole wit’ 3 of its 6 pieces gone. Forty feet of new crawlway gets hid like dat in about 11 minutes. Both sides build after lights-out an’ fluff by dawn now, an’ no parent can tell how much of da furniture is fort anymore."
 },
 "Crawlway Warfare": {
  "label": "Crawlway Warfare, Yah",
  "desc": "Nobody stands up in da livin’ room no more, an’ overhand t’rowin’ turns into lobbin’, done from da crawlway floor wit’ a 3-foot shelf board on a rolled-up towel tipped to 60 degrees. Da crawlways run 200 feet across da 2 allied houses, an’ every exchange comes from behind a cushion lip, droppin’ hit rates from 1 in 4 to 1 in 11. An afternoon of fightin’ moves da front about 6 feet, or 3 cushions, eh."
 },
 "Lived-In Finish": {
  "label": "Da Lived-In Look",
  "desc": "Hidin’ stuff turns into its own trade: matched loft, matched rumple, an’ a few dents pushed in by hand so a Fluffered cushion looks like somebody just got up off it. A good crew can hide a sock battery behind a sofa in under 20 minutes. Da giveaway’s always da seam line, where 4 cushions done in 9 passes stand at exactly 5 inches, a row too even for anybody to’ve sat on it."
 },
 "Under-Table Network": {
  "label": "Da Under-Table Network",
  "desc": "Passages get run under da dinin’ table, da beds, an’ da piano to hook da crawlways togedder, 150 feet all told, mostly at a crawlin’ height of 30 inches. Da parents get told once da network’s done, an’ one of ’em looks it over wit’ a flashlight an’ props up da saggy sheet ceilin’s wit’ yardsticks every 6 feet. Dere’s 4 ways in, 2 of ’em hid behind da drapes."
 },
 "Tunnel Fluffers": {
  "label": "Tunnel Fluffers, Eh",
  "desc": "Da power goes out for 38 minutes an’ da Fluffers go under da table anyway, puffin’ back up floor pads squashed to nuttin’ by a day of crawlin’. Dey get cranked by feel in da dark, wings folded, da 3:1 crank turned half speed so da slip clutch never trips. Two crews run smack into each udder under da piano in a passage neider one knew hooked up, an’ da map dat comes out of it, drawn on a pizza box, is da most valuable paper of da whole week."
 },
 "Yardstick Sling": {
  "label": "Da Yardstick Sling",
  "desc": "A pillowcase sling gets tied on a 3-foot yardstick an’ swung 2-handed from behind da cushion wall, where dere’s still room to kneel up. It reaches 32 feet against a hand-t’rown sock’s 20, an’ da arc clears da wall widout showin’ da t’rower. Four get built, an’ 2 get taken away inside a day ’cause dere’s no place indoors safe to swing ’em, 1 of ’em after it met da ceilin’ fan."
 },
 "Unpinned From Below": {
  "label": "Unpinned from Underneat’",
  "desc": "A crawl gets pushed in under da udder side’s fort, 22 feet t’rough da under-table network, takin’ 4 hours an’ 2 kids workin’ in shifts. At da end, da clothespins holdin’ up da enemy ceilin’ get unclipped from underneat’, an’ 8 feet of fleece comes down in a second an’ a half. Both sides start checkin’ under deir own floors wit’ a flashlight every mornin’, an’ dat becomes standard practice, eh."
 },
 "The Fluffer Guild": {
  "label": "Da Fluffer Guild",
  "desc": "Da Fluffer operators get organized. To join ya gotta bring a squashed cushion back to full loft in exactly 9 passes, do a clutch check from memory, an’ say da recliner rule word for word: never fluff a seat a grown-up’s sittin’ in. Dere’s 91 members across da subdivision da first week, an’ 14 get turned down for fluffin’ a recliner wit’ somebody in it an’ 1 for buildin’ a Fluffer wit’ no clutch."
 },
 "The Basement Keep": {
  "label": "Da Basement Keep",
  "desc": "A main stronghold gets built down in da host basement wit’ a real room inside, 7 feet long by 6 wide an’ 4 feet at da ceilin’, roofed wit’ 2 sheets of plywood outta da garage an’ walled 2 feet thick in mattresses, so da outside comes to 11 by 10. Dere’s 1 per alliance, not 1 per house. It’s cool, dim, drippin’ about a drop a second from a window well, an’ big enough for 4 sittin’ down. Inside it stays near 64 degrees no matter what da upstairs thermostat says."
 },
 "Keep Refluffing": {
  "label": "Refluffin’ da Keep",
  "desc": "Da keep goes on a maintenance rotation: every mattress top, wall cushion, an’ floor pillow run t’rough da Fluffer, 9 passes apiece, every 3 hours, by a regular crew of 6. Da keep never looks sat in. Scouts from da house across da street report back dat da basement bunch must not be fightin’ at all, which is what dey’re supposed to tink, an’ it’s wrong."
 },
 "Basement Bailey": {
  "label": "Da Basement Bailey",
  "desc": "A second wall goes up behind both allied fronts, wrappin’ round da keep an’ da main stash of socks an’ marshmallows: 4 twin mattresses stood up on end an’ da sectional’s 3 backs, 60 feet around at 5 feet high. Takin’ eider upstairs fort don’t end nuttin’ no more. Two full raids make it to da basement stairs in one night, an’ neider one gets past da inner wall."
 },
 "The Fluffer Registry": {
  "label": "Da Fluffer Registry",
  "desc": "Every Fluffer in service gets a number on maskin’ tape, logged in a spiral notebook, an’ put wit’ a fort, wit’ cranks turned an’ cushions fixed written down for each one. Dere’s 406 on da books across da subdivision an’ 11 nobody can find, 3 of ’em last seen at a sleepover. Da registry outlasts every fort it was wrote up to supply an’ ends up, way later, da oldest record eider household’s still got."
 },
 "Ring Within a Ring": {
  "label": "Ring Inside a Ring",
  "desc": "Da rain gets near 4 inches, da gutters run 5 inches deep, an’ every parent tells every kid to stay put in whatever house dey’re in. Da host house answers wit’ a fort inside a fort: an outer ring of chair-an’-sheet forts round da livin’ room an’ an inner ring of mattresses on da couch frame, 2 feet taller, so pillows lob right over da first one. A raider who takes da outer ring lands in da 4-foot gap between ’em, lit up by 50 holiday lights an’ pelted from 2 sides."
 },
 "Trash-Bag Armor": {
  "label": "Trash-Bag Armor, Eh",
  "desc": "Da Flash Flood Warnin’ comes in at 9:40 at night an’ da household heads upstairs, which is right: get to higher ground when da water’s comin’ up an’ never wait to see how high it gets. Da basement keep gets left to 6 inches of water. Upstairs, da hallway fort’s cushion walls get wrapped in 13-gallon kitchen bags to keep ’em dry, an’ pillows skid off da plastic now instead of landin’, cuttin’ what dey do by about 66 percent. Da walls last t’ree times as long."
 },
 "Armoured Fluffer": {
  "label": "Da Armored Fluffer",
  "desc": "Only 2 of da household’s Fluffers make it up da stairs, an’ both get rebuilt to work under pillow fire in a hallway 36 inches wide. Each one gets a curved cookie-sheet shield over da roller an’ a trash-bag apron on da crank side, addin’ 4 pounds to a machine meant to weigh 3. Crew gettin’ hit while refluffin’ drops by two thirds. Cushions fixed per hour drop by a fifth, an’ every crew dat gets offered da shield takes it, eh."
 },
 "Bag Crews": {
  "label": "Da Bag Crews",
  "desc": "Da neighbors from da one-story house across da street show up at 1:30 in da mornin’ wit’ 2 kids an’ a cat, an’ baggin’ turns into a regular job: 3 people per fort, 40 kitchen bags a night, passed hand to hand from da box under da sink up 14 stairs in 11 trips. Da baggin’ goes from just da front to da whole way around, about 200 square feet of wall. Spots wit’ no bag get marked on a map on da back of an envelope an’ turn into da usual pillow target."
 },
 "Fluffer Doctrine": {
  "label": "Da Fluffer Doctrine",
  "desc": "Refluffin’ gets a doctrine, not a manual: refluff before da sleepers go flat, never refluff while a grown-up’s watchin’ from da landin’, never refluff da same cushion twice in one night. Dey argue about it from 2:00 to 3:15 in da mornin’ an’ take it pretty much as is. Da t’ird rule’s dere ’cause a cushion fluffed twice stands 1 inch taller dan 9 passes allow, an’ a cushion dat looks fresh-fluffed is a cushion somebody swipes."
 },
 "Fellowship Hall Gatehouse": {
  "label": "Fellowship Hall Gatehouse",
  "desc": "At 8:00 in da mornin’ da family evacuates to da fellowship hall of da church up on da ridge, 60 feet above da creek, wit’ 1 go-bag each an’ da Blanket. Da first fort’s up by 10: 2 foldin’ tables under a 52-by-114-inch tablecloth on loan from da altar guild. Out front dere’s a gatehouse of 4 foldin’ chairs wit’ a way in dat bends twice, so nobody can rush straight in. A slot in da tablecloth overhead drops 1 cocoa packet on every visitor, yah."
 },
 "Two Ranks of Fifteen": {
  "label": "Two Ranks of Fifteen, Eh",
  "desc": "By noon da hall’s got 140 evacuees, 30 of ’em kids, an’ da kids quit t’rowin’ alone. Dey line up in 2 ranks of 15 behind a row of foldin’ tables an’ t’row donated stuffed animals on a called count. One big release puts 30 bears in a 20-foot square inside 2 seconds, which no one arm ever managed. Gettin’ good enough takes 9 sessions, an’ about a third never get dere, mostly da ones under 5."
 },
 "Fluffer Corps": {
  "label": "Da Fluffer Corps",
  "desc": "Refluffin’ turns into a trade wit’ its own crews: 9 operators wit’ Fluffers hauled in from 6 households, workin’ in a rollin’ line along da donation pile at da edge of da hall. Dey puff back up a solid 40-foot run of donated pillows every pass, squashed flat in da bags on da way over, an’ turn a bare corner everybody’s fightin’ over into a stocked fort in under 4 minutes. Builders grab from pillows da Fluffers fixed now instead of from da donation truck, an’ da truck ain’t da only supplier no more."
 },
 "First Catapult": {
  "label": "Da First Catapult",
  "desc": "Da first catapult gets put togedder from a foldin’ chair, a broom handle, an’ 4 bungee cords took widout askin’ from a volunteer’s pickup an’ missed inside an hour. It launches a rolled-up pair of socks a measured 60 feet down da hall, about 3 times as far as ya can t’row, den falls apart on da second try. Puttin’ it togedder took 2 hours an’ 5 kids."
 },
 "Fluffer Liaison": {
  "label": "Da Fluffer Runner",
  "desc": "A runner, age 9, gets put between da Fluffer crews an’ da catapult crews so refluffin’ an’ bombardin’ quit happenin’ on da same cot at da same time. Before da runner, 4 Fluffers get knocked over by socks from deir own side in 2 days. After, none, an’ da runner, in a reflective vest outta da church van, is da only one in da hall allowed to stop a catapult in da middle of loadin’."
 },
 "Inner-Tube Launcher": {
  "label": "Da Inner-Tube Launcher",
  "desc": "A flat-shootin’ engine gets built from a bicycle inner tube stretched between 2 coat-rack poles, aimed instead of lobbed. It puts one rolled sock t’rough da 8-inch gap in a tablecloth fort door at 70 feet, wit’ 1 shot in 4 landin’ inside a 2-foot circle. Reloadin’ takes 50 seconds, an’ dat’s da whole problem wit’ it."
 },
 "Lookout Tower": {
  "label": "Da Lookout Tower",
  "desc": "A tower dat stands on its own gets stacked from empty cot boxes an’ folded tumblin’ mats, 4 feet wide at da bottom an’ 2 at da top, wit’ a lookout platform da volunteers cap at 6 feet. From up dere a spotter can see all 96 chairs an’ 12 tables in da hall an’ calls catapult shots by table number. It’s da first ting in da shelter built to look out from instead of hide in."
 },
 "Counter-Catapults": {
  "label": "Counter-Catapults, Yah",
  "desc": "Catapults get built now just to knock over udder catapults, out to 70 feet. Four are workin’ across da hall an’ 3 get knocked out inside 2 days, 2 of ’em by udder catapults an’ 1 by da church custodian. How long a catapult lasts, middle of da pack, drops to 9 shots, eh."
 },
 "Fluff-and-Build Cycle": {
  "label": "Da Fluff-an’-Build Cycle",
  "desc": "Da two trades get hooked togedder for real: a Fluffer crew fixes a pillow in 9 passes, builders set it in a wall inside an hour while it still springs back, an’ da flat ones go back in da rotation. Walls built from pillows fluffed inside da hour stand about 3 inches taller an’ stay up longer dan walls built from pillows off a cot. Forts built per kid per day just about double, from 2 to 4, an’ never drop back."
 },
 "Canned-Goods Trebuchet": {
  "label": "Da Canned-Goods Trebuchet",
  "desc": "A counterweight engine gets built on a 6-foot closet rod pivotin’ between 2 stacked tables, wit’ a laundry bag holdin’ 30 cans of donated green beans for weight. It t’rows a pillow 90 feet, da whole length of da hall to da kitchen pass-t’rough, against da 70 of anyting else in service. Buildin’ it takes 9 hours. It outshoots every counter-catapult in da hall, which ends dat advantage in one afternoon."
 },
 "Sock Factory": {
  "label": "Da Sock Factory",
  "desc": "A real production line opens up at a foldin’ table wit’ a foreman, age 11, an’ 6 workers rollin’ donated socks into rounds. Dey turn out 60 to 90 an hour, da pile on hand gets past 2,000, an’ every round gets checked for a 3-inch width, a tight roll, an’ a fit in da catapult cup before it gets stacked. About 1 in 8 gets turned down, an’ da rejects go to evacuees who need socks, which is most of ’em."
 },
 "Refluffing Line": {
  "label": "Da Refluffin’ Line",
  "desc": "Da sock factory gets a matchin’ Fluffer line runnin’ da udder way down da table: one crew rolls socks into rounds, da udder runs pillows squashed by hits back t’rough da 14-inch roller so da walls never go flat. It settles in near 300 pillows fixed a day against 1,900 rounds rolled. Da 2 lines get timed against each udder on a whiteboard by da kitchen pass-t’rough, an’ for da first 3 days da Fluffers are winnin’."
 },
 "Catapult Shops": {
  "label": "Da Catapult Shops",
  "desc": "Catapults quit gettin’ built right where dey’re used: 2 shops get set up in da Sunday school rooms behind da hall, wit’ frames, broom handles, an’ cut bungee cord. Buildin’ time drops from 9 hours to 3, an’ a busted catapult gets rebuilt instead of tossed. Spares on hand come to 4 whole frames an’ 60 feet of bungee cord, borrowed wit’ permission dis time."
 },
 "The Felt Works": {
  "label": "Da Felt Works",
  "desc": "Da church quiltin’ circle, 11 members an’ 3 sewin’ machines, takes over coverin’ Fluffer rollers, in wool felt instead of polyester, ’cause polyester felt pills up an’ leaves lint on every cushion it touches, an’ da cushion’s da whole point. Output goes from 4 rollers a week to 60. Da material call gets made one time, by a quilter who rubs 2 samples on a cot blanket 500 times each, an’ nobody ever goes back on it."
 },
 "Donation Points": {
  "label": "Da Drop-Off Spots",
  "desc": "Clean pillows get to be da holdup instead of workers, an’ drop-off spots open up away from da shelter: a fire station, a grocery store, a bank lobby, an’ a funeral home, each takin’ in about 600 tings a day, a fifth of ’em firm enough for fort walls. Haulin’ averages 3 miles by van. Da middle school gym opens as da second shelter dat evenin’, an’ 2 of da 4 spots get fought over between da 2 shelters an’ change hands 3 times."
 },
 "Cot Casemates": {
  "label": "Da Cot Casemates",
  "desc": "Da first supply pallet shows up wit’ 150 cots, 150 grey blankets 60 by 80 inches, an’ a laminated card sayin’ 1 blanket per evacuee. Fort walls are 2 cots thick now, set on deir sides 25 inches apart, an’ da space between gets roofed wit’ standard-issue blankets to make little rooms right inside da wall. T’rowers kneel in dere an’ fire t’rough da gaps between da cot legs, covered from everyting but da trebuchet."
 },
 "Masking-Tape Ranges": {
  "label": "Maskin’-Tape Ranges",
  "desc": "Shootin’ quits bein’ guesswork: maskin’-tape marks go down on da floor every 10 feet out to 80, an’ every catapult gets walked onto its target wit’ 3 rangin’ socks. Hits at max range go from 1 in 11 to 1 in 4. A rangin’ book gets kept for each catapult, on da back of a potluck sign-up sheet, an’ copied every time da crews switch."
 },
 "Roller Standardization": {
  "label": "One Roller for All, Eh",
  "desc": "Every Fluffer in service gets brought to one pattern, a 14-inch roller on a 3:1 crank dat fixes a cushion in 9 passes, so any roller fits any frame in eider shelter. Some 900 off-pattern machines get called back across da county an’ re-felted. Da ratio dey pick is da one argued out on graph paper before it rained at all, unchanged, an’ da 2 people who argued it are over in row C an’ nobody asks ’em."
 },
 "Gymnasium Front": {
  "label": "Da Gymnasium Front",
  "desc": "Da fight outgrows one buildin’ an’ runs across 2 shelters, da church hall an’ a middle school gym 94 by 50 feet holdin’ 180 cots in 12 rows of 15. Da gym’s main wall is one line of cots on deir sides, 2 high an’ 94 feet long, wit’ both allied districts behind its one shared face. Da territory gets mapped on notebook paper, held by 1 kid per side, an’ fixed up about 9 times a day. Over 60 kids are in it now, wit’ 1 catapult per 4 cot rows."
 },
 "Fluffer Reconnaissance": {
  "label": "Fluffer Scoutin’",
  "desc": "Fluffer crews get sent down udder families’ cot rows offerin’ free refluffin’ an’ come back tellin’ what dey saw, which is more dan any scout gets, ’cause a kid wit’ a Fluffer’s got a reason to walk slow past every cot. All 4 sectors, rows A t’rough P, get mapped like dat in 2 days. Both sides figure out what’s goin’ on about da same time an’ start readin’ each udder’s pillows for intelligence: a row at full loft, 9 passes even, is a row about to turn into a fort."
 },
 "Cot Ravelins": {
  "label": "Da Cot Ravelins",
  "desc": "T’ree-cornered outworks of 3 cots apiece get set 10 feet out in front of da main cot wall, each roofed wit’ 1 standard-issue blanket an’ held by 2 kids. A raid on da wall’s gotta split around ’em or take ’em first now. Six get built along da gym’s 94-foot front, an’ da volunteers, after a 20-minute meetin’, call ’em legal so long as da aisles stay 4 feet wide."
 },
 "Bleacher Salient": {
  "label": "Da Bleacher Bulge",
  "desc": "Da line quits bein’ straight. T’ree bulges push into da udder side’s rows 2 to 4 cots deep, each one defended on 3 sides an’ each needin’ about 40 percent more kids per foot of front. Each one’s held by 2 catapults shootin’ off in different directions. Two of da 3 get given up on purpose inside 2 days; da t’ird, which reaches da bleachers, gets held, ’cause da bleachers are 8 rows high an’ da warmest seats in da gym."
 },
 "Counter-Fluffer Fire": {
  "label": "Shootin’ at da Fluffers",
  "desc": "Catapults start aimin’ at Fluffer crews as deir own kind of target, figurin’ a fort dat can’t get refluffed is flat by mornin’. It’s da first time in da whole war da gear’s worth more dan da spot it’s holdin’. Fluffer losses in da first 3 days come to 31 machines knocked over or jammed, an’ every one gets replaced from da quiltin’ circle’s felt works inside 24 hours."
 },
 "Steady Bombardment": {
  "label": "Steady Bombardment, Eh",
  "desc": "Lobbin’ goes steady instead of now-an’-den, 40 socks an hour per catapult across 9 catapults in da gym. Nuttin’ gets aimed at a person; da target’s da wall itself, an’ a casemate wall dat used to stand a week now lasts 2 days. Both sides start fixin’ under fire as a regular job, an’ da volunteers keep da shootin’ to between 4:00 an’ 8:00 in da evenin’."
 },
 "Supply Carts": {
  "label": "Da Supply Carts",
  "desc": "Ammo’s gotta get moved now from da donation room in da school cafeteria to da gym, a haul of 500 feet down 2 hallways. Laundry carts get taken, 2 per side, from a custodian nobody asks, 1 of ’em saved for green beans for da trebuchet, da routes get set, an’ how fast stuff shows up, about 400 socks an hour, sets da pace of da whole war. Da front forts hold 90 minutes of supply."
 },
 "Fluffer Convoy": {
  "label": "Da Fluffer Convoy",
  "desc": "Refluffin’ goes mobile. A convoy of 6 Fluffers rides from da church to da gym in da church van, 2 miles dat take 4 hours ’cause da driver turns around at every flooded road an’ never drives into water: a foot of movin’ water can float most cars. Each machine brings its own pillowcase of 4 squashed pillows for cot rows dat got none, an’ doctrine calls da Fluffer a supply engine now instead of a toy."
 },
 "Pulley Line Head": {
  "label": "Da Pulley Line",
  "desc": "A rope-an’-pulley line gets strung 40 feet from da gym stage down to da cot floor, haulin’ Fluffers up front in laundry bags widout nobody walkin’ ’em t’rough da rows. About 60 machines a day show up at da head. It gets took down twice, once by trebuchet fire an’ once by da custodian, an’ rebuilt twice, an’ da second rebuild moves it 20 feet farther back from da front, which nobody minds."
 },
 "Hallway Blockhouses": {
  "label": "Da Hallway Blockhouses",
  "desc": "Little roofed forts go up every 50 feet along da 500-foot hallway route from da cafeteria to da gym, each one built from 2 cots an’ 1 standard-issue blanket an’ held by 2 kids. Deir job’s guardin’ da laundry carts. Dere’s 10 of ’em, an’ da 3 closest to da gym are also, everybody agrees, where da cocoa urn stops, eh."
 },
 "Sock Depots": {
  "label": "Da Sock Depots",
  "desc": "Front stashes get set up behind each cot sector, 6 laundry baskets holdin’ 1,500 rolled socks apiece. Time from askin’ to gettin’ it at da wall drops from 25 minutes to 4. Two depots sit inside range of da trebuchet up in da bleachers an’ get moved after da first one gets hit, scatterin’ 1,100 socks across rows F t’rough H, which get rolled back up by bedtime. Outside, da rain gets past 9 inches."
 },
 "Cart-Drawn Fluffers": {
  "label": "Cart-Pulled Fluffers, Eh",
  "desc": "Fluffers get bolted onto da shelter’s laundry carts an’ pulled down da cot rows by crews of 4, so da drive comes off da cart wheels ’stead of da crank. Da 14-inch felt roller’s geared to da axle at da same 3:1 an’ only turns when da wheels turn, so da slip clutch stays just as careful as before at 10 times da output, eh. A loaded cart fluffs up a whole row of 16 cots’ pillows at a walkin’ pace an’ takes 4 people to stop, ya know."
 },
 "Lights-Out Batteries": {
  "label": "Lights-Out Batteries, Yah",
  "desc": "Da cot catapults go up on wheeled laundry carts an’ get moved every night after lights-out, 4 to a battery, so no volunteer finds one in da same spot twice. A move takes 20 minutes in da dark wit’ 2 of da gym’s 24 overhead lights on, an’ confiscations drop by three quarters. Da catch is aim: da first pillow from a new spot lands 6 feet wide on average, usually on a sleepin’ grown-up, eh."
 },
 "Cardboard Partition Act": {
  "label": "Da Cardboard Partition Act",
  "desc": "Privacy partitions show up flat-packed, cardboard panels 48 inches high an’ 72 inches wide, 2 per family, an’ everyt’ing out front of da forts gets rebuilt wit’ ’em. Every fort gets 4 outworks a side pushed 6 feet out, plus a redoubt of 8 panels holdin’ 80 pillows in reserve. Da shelter manager puts out a memo sayin’ partitions are for privacy, not fortification, eh. Da memo gets taped to a partition, which den gets used as a fort door."
 },
 "The Cot Citadel": {
  "label": "Da Cot Citadel",
  "desc": "A fort wit’ a bunch of rooms an’ a roof dat actually holds goes up at da far end of da gym: 5 rooms of standin’ cots an’ partitions on a footprint 34 by 22 feet, wit’ 3 tablecloths an’ 11 standard-issue blankets for a ceilin’, propped at 5 feet by 6 broom handles. It gets a name, Fort Row P, wrote on a partition at da entrance. Every cot in da buildin’ now gets found by how many rows it is from da Citadel, eh. Buildin’ it took 60 person-hours, an’ da garrison runs 28."
 },
 "Citadel Re-Lofting": {
  "label": "Citadel Re-Fluffin’",
  "desc": "Da whole Citadel gets kept fluffed up full-time: 11 Fluffer crews on rotation, every pillow an’ folded-blanket cushion fluffed back up inside 72 hours of somebody sittin’ on it. Every piece gets its 9 passes under da 14-inch felt roller, an’ da slip clutch clicks any time a crew cranks too eager. Dey go t’rough 900 pillows a day, not one of ’em new, eh. From da cot rows da Citadel looks forever, impossibly fresh-built, an’ everybody inside knows dat’s a political statement, ya know."
 },
 "The Cot Row Draft": {
  "label": "Da Cot Row Draft",
  "desc": "Joinin’ da war isn’t voluntary no more. Every family across 4 cot rows gets assessed at 1 combatant per 2 kids, an’ dat makes a roll of 140. Exemptions go to anybody hurt, anybody holdin’ a workin’ phone charger by 1 of da gym’s 6 outlets, an’ da 11 crews already on Fluffer duty. About 70 percent show up, eh."
 },
 "Heavy Cot Catapults": {
  "label": "Big Heavy Cot Catapults",
  "desc": "Counterweights get bumped up to 16 cases of donated bottled water, about 400 pounds, on frames of 3 lashed-togedder cots dat need a crew of 9. Range reaches da whole 94-foot length of da gym, an’ one king pillow knocks a partition wall flat. Two get built, an’ each one ties up its crew a whole day every time it moves, ’cause 2 cot rows gotta be renumbered, eh."
 },
 "Standing Pillow Guard": {
  "label": "Da Standin’ Pillow Guard",
  "desc": "Fightin’ quits bein’ casual at a roster of 90 across both ends of da gym. Dere’s 4 ranks, marked by da color of a second intake wristband, uniforms made outta 23 lost-and-found sweatshirts, an’ a chain of command dat runs every order t’rough 1 person in row P. Attendance gets taken in da breakfast line an’ stays over 80 percent for 6 days straight, eh."
 },
 "Fluffer Duty Roster": {
  "label": "Da Fluffer Duty Roster",
  "desc": "Fluffer duty quits bein’ volunteer an’ starts gettin’ assigned on da shelter chore chart, at 400 shifts in one week. Da Fluffer Guild says an untrained hand cranks faster dan da 3:1 gearin’ likes an’ quits before da 9th pass, gets overruled, an’ turns out right inside 4 days when da spread in pillow height goes from 14 percent to 31. Trainin’ comes back, on da same chore chart, an’ nobody says nuttin’ about it."
 },
 "Laundry Basket Pillboxes": {
  "label": "Laundry Basket Pillboxes, Eh",
  "desc": "Low firin’ posts get built for da standin’ guard by da hundred: a round laundry basket flipped upside down on a folded tumblin’ mat, 34 inches off da floor, wit’ a standard-issue blanket t’rown over it an’ da weave left open for slits. Each one holds 1 kid an’ 12 balled-up socks. By da end of da week dere’s 140 of ’em, an’ da volunteers quit countin’ at 100, eh."
 },
 "Clipboard Officers": {
  "label": "Da Clipboard Officers",
  "desc": "Command splits off from da fightin’: 11 officers across both ends of da gym, handed spare clipboards from da intake desk, an’ not one of ’em has t’rown a pillow in 4 days. Orders get wrote down ’stead of hollered, about 30 a day, a third of ’em catapult instructions. From decision to pillow in da air takes 6 minutes, most of it spent findin’ a pen, eh."
 },
 "Fluffer Clauses": {
  "label": "Da Fluffer Clauses",
  "desc": "Truce terms start coverin’ da machines: each end of da gym can hold 3 Fluffers, each can only fluff its own cots, an’ nobody turns a crank where da udder side’s forts can see. Dose clauses run longer dan da ones about t’rowin’, an’ dey name da 14-inch roller, da 3:1 gearin’ an’ da slip clutch right out so nobody can claim a loophole. Both sides stick to da count an’ neider one sticks to da sight line, eh."
 },
 "Quiet Hours Armistice": {
  "label": "Quiet Hours Armistice, Yah",
  "desc": "A written armistice gets drafted on a flattened cot box by delegations of 6 an’ covers 10 at night to 7 in da mornin’. It sets boundaries right down to da cot, pillow limits at 300 a side, a ceilin’ of 4 catapults apiece, an’ terms for startin’ back up at breakfast. Four papers are in force all at once, taped to 4 different partitions, an’ 2 of ’em fight over da same row, eh."
 },
 "Over the Partition": {
  "label": "Over Da Partition",
  "desc": "Catapults get aimed at forts da crews can’t even see, lobbin’ pillows over 48-inch partitions on corrections called down by walkie-talkie from a spotter up on da top tier of da bleachers. From spottin’ to correction takes 90 seconds, an’ da hit rate on a fort ya can’t see settles around 1 in 7. Da back side of every partition’s a target for da first time, an’ 3 families who figured dey had privacy find out udderwise, eh."
 },
 "The Masking Tape Commission": {
  "label": "Da Maskin’ Tape Commission",
  "desc": "A standin’ board of 9 sets up by da cocoa urn to sort out da armistices: 4 kids from each end of da gym plus 1 volunteer who’s officially neutral an’ unofficially in charge of da cocoa. It rules on 41 fights in a week an’ folks go along wit’ 34 of ’em. Boundary marks of maskin’ tape go down every 50 inches along 1,250 feet of cot line across 3 shelters, eh."
 },
 "The Phantom Pillow Drive": {
  "label": "Da Phantom Pillow Drive",
  "desc": "Fluffin’ gets used big-time to fake a donation dat never came. Over 1 night, 9 crews run 1,200 flattened pillows t’rough da 14-inch roller at 9 passes each, so da mornin’ count at da east-side shelter shows a pillow drive an’ justifies a second blanket per cot. It works, eh. Da intake ledger says 1,200 new pillows an’ da county warehouse says 0, an’ folks on both sides still bring it up decades later for opposite reasons."
 },
 "The Zamboni Line": {
  "label": "Da Zamboni Line",
  "desc": "Wit’ downtown floodin’, da county opens up da hockey arena, da ice covered over wit’ insulated floorin’ an’ 1,400 cots, an’ inside 2 nights one named line runs da whole way round da concourse. It’s 1,900 feet of partitions, hooked up to 46 basket pillboxes an’ 3 sleepin’-bag tunnels, an’ it’s named after da Zamboni gate where it starts. Everyt’ing behind it counts as held, an’ nobody can say from what, eh."
 },
 "Total Pillow War": {
  "label": "Total Pillow War, Holy Wah",
  "desc": "A campaign across da whole network of 7 shelters, wit’ offensives all lined up on one timetable read out over 1 radio channel. Da river’s still crestin’ an’ da war’s outlasted da rain dat started it by 9 days, wit’ over 300 kids in it. Every day across all fronts dey go past 12,000 pillow t’rows, a third of ’em by catapult, wit’ 40 cot catapults workin’ at 7 sites, eh."
 },
 "Pattern Catapults": {
  "label": "Pattern Catapults, Yah",
  "desc": "Catapult buildin’ gets standardized to one drawin’ taped on da cocoa urn: 1 regulation cot, 75 by 25 inches, 1 broom-handle arm, 1 pillowcase sling. Parts off any wreck fit any survivor now, eh. Ninety get built to da pattern in 2 weeks against 40 mixed ones still workin’, an’ gettin’ a busted catapult back on da line drops from 2 days to 4 hours."
 },
 "General Call-Up": {
  "label": "Da General Call-Up",
  "desc": "Every kid old enough in da shelter network gets called up all at once, 1,100 of ’em inside 48 hours. Production goes all in on ammo, wit’ donated clot’es stuffed into spare pillowcases at 4,000 a day. Attendance at da 4 story-time sessions every day drops under half an’ doesn’t get wrote down dat week, eh."
 },
 "Fluffer Divisions": {
  "label": "Da Fluffer Divisions",
  "desc": "Fluffin’ gets its own command, 4 divisions of 90 Fluffers each, rankin’ right alongside da catapults ’stead of under da laundry crew. Folks fight da change for 2 laundry cycles, an’ one number settles it: forts wit’ a division attached stay standin’ 3 times as long, ’cause a cushion dat gets its 9 passes under da 14-inch roller doesn’t slump. Fluffer officers get saluted from here on, eh."
 },
 "Laundry Cart Blitz": {
  "label": "Da Laundry Cart Blitz",
  "desc": "Piled-up socks an’ speed push fortifyin’ right out. Forts get dropped in da middle of da campaign for fast columns of 11, each one pushin’ a laundry cart wit’ 400 balled socks an’ a light catapult, coverin’ da 1,900-foot concourse in under 6 minutes. Average fights drop from 50 minutes to 9, dey get 600 feet past da Zamboni Line, an’ da front moves up 1 seatin’ section a day, eh."
 },
 "Blitz Fluffing": {
  "label": "Blitz Fluffin’",
  "desc": "Da doctrine flips. ’Stead of fluffin’ ground dey already hold, Fluffer carts run out ahead of da sock columns, rollin’ dere 14-inch felt drums over da flattened pillows of sections nobody’s took yet at 9 passes a pillow, so da attack shows up on beddin’ it can build wit’ right away. Fronts move 11 sections in a week for da first time in da war. More dan half da forward Fluffers get lost, mostly confiscated by 2 cranky volunteers, an’ dey keep da doctrine anyhow, eh."
 },
 "Back-Corridor Raids": {
  "label": "Back-Hallway Raids",
  "desc": "Bunches of 4 carryin’ 60 socks apiece sneak into da arena’s service hallways behind da udder side’s line for up to 3 hours. Dey go after donation storerooms, pillow bins, an’ catapult parks ’stead of forts, an’ 9 get hit in a week, costin’ about 6,000 pillows. No route goes outside da buildin’, ’cause da parkin’ lot’s got 14 inches of floodwater dat can hide open manholes an’ downed lines. About a third of da bunches miss check-in an’ turn up asleep in somebody else’s fort, eh."
 },
 "Pillow Ballistics": {
  "label": "Pillow Ballistics, Eh",
  "desc": "Firin’ gets figured ’stead of guessed: range, arm length, water-case counterweight an’ pillow grade, firm, medium or soft, all worked out on homework paper before da first t’row. Four catapults firin’ 1 solution land inside a 9-foot circle at 140 feet. A battery clerk, age 12, gets appointed, an’ every crew’s notes go into 1 table taped up on da scoreboard, eh."
 },
 "Under the Stands": {
  "label": "Under Da Stands",
  "desc": "Command goes clear outta sight, into da hollow under da lower seatin’ bowl, about 20 feet below da concourse, an’ ya get in t’rough 2 maintenance doors. Da arena engineer only lets it happen after checkin’ da space sits 31 feet above da river’s forecast crest. Up on da floor, 40 forts get kept fresh-made an’ totally empty for decoys, an’ da udder side spends 3 days besiegin’ ’em, eh."
 },
 "The Hall B Fort City": {
  "label": "Da Hall B Fort City",
  "desc": "A federal disaster declaration brings da convention center online wit’ 5,000 cots across 3 exhibit halls, an’ da forts get big enough to put up whole families overnight. Da biggest one holds 40 to 60 folks in 41 rooms across 120 by 90 feet of Hall B, at a crawlin’ height of 30 inches. Sleepin’-bag tunnels hook rooms up to more rooms still gettin’ added on, past 900 feet of mapped passage an’ who knows how much more, eh."
 },
 "Hall-Scale Fluffers": {
  "label": "Hall-Size Fluffers",
  "desc": "Fluffers get built to convention-center size, da felt roller stretched out on hinged wings from 14 inches to 12 feet an’ driven off da wheels of a pallet jack, an’ run down whole cot streets every night. One unit fluffs up 11 named rows in a shift, at 9 passes a row. Folks quit tellin’ new donations from upkeep, an’ in shelter talk a fluffed pillow just gets called new, eh."
 },
 "Laundry Cycle Staff Course": {
  "label": "Laundry Cycle Staff Course, Yah",
  "desc": "Plannin’ turns into somet’ing ya get taught, at a foldin’ table by da washers. Twenty-two kids study laundry rotation, cocoa schedules, an’ da 9 campaigns fought so far, in a course dat runs 4 evenings. Graduates plan 3 laundry cycles ahead ’stead of 1 afternoon, timin’ every offensive round da 6:00 in da mornin’ fort teardown, an’ campaigns run about twice as long, eh."
 },
 "Fort School": {
  "label": "Da Fort School",
  "desc": "Technique gets taught to da new folks in a 6-session course in a shelter classroom. Dere’s a right way to tuck a blanket corner, 4 tucks of 3 seconds each, a right way to swing a pillow, a 4-person drill for puttin’ up da Fort Plan, an’ a wrote-down order for takin’ a fort down at laundry call. About 40 students sign up each intake, an’ 80 percent graduate, eh."
 },
 "The Fluffer Academy": {
  "label": "Da Fluffer Academy",
  "desc": "A school gets started dat teaches nuttin’ but fluffin’: crank pace on da 3:1, readin’ a flat spot, how da slip clutch acts, an’ 40 hours of crankin’. Da entrance exam is one cushion brung back to full loft in exactly 9 passes, judged by eye. Da lessons start wit’ da original drawin’ at 4 squares to da inch, copied from a copy of a copy, da arrow still labeled “flat goes in here” an’ da 14-inch roller drawn a little outta round, eh."
 },
 "Cot Row Districts": {
  "label": "Cot Row Districts, Eh",
  "desc": "Hall B gets split into 11 districts, each wit’ its own lost-and-found, pillow bin, catapult park, an’ a roll of about 200. Orders from da middle go by da cot-row post, carried twice a day by 8 volunteers under age 12, an’ make it to da farthest district in a day an’ a half. Three districts make more stuffed pillowcases dan dey use an’ get taxed a fifth of it, about 900 a week apiece, eh."
 },
 "The Fluffer Works": {
  "label": "Da Fluffer Works",
  "desc": "Da network goes industrial on fluffin’. Forty workshops at da cot-repair stations crank out Fluffer after Fluffer on one pattern, 14-inch rollers cut from carpet tubes an’ wrapped in felt from donated wool blankets so dey don’t crush at full crank on da 3:1, an’ dey field a standin’ park of 1,100 machines. Whole districts get fluffed up overnight, an’ da words flat pillow quietly drop outta da language. Da workshops get guarded heavier dan da catapults dey supply, eh."
 },
 "The Shelter Gauge": {
  "label": "Da Shelter Gauge",
  "desc": "One standard gets decreed for every fort in da network, set on purpose above da biggest one standin’ so no fort meets it an’ every fort’s gotta grow: 12 cots, 6 chairs, 3 blankets, 18 clothespins, da Fort Plan times t’ree, on a footprint of 225 by 75 inches. Surveyors head out wit’ a tape measure an’ a binder an’ report not one fort meets da gauge, which is da whole point. Da hall dat wrote da decree has got da most spare cots an’ can afford to build to it first, eh."
 },
 "The Great Rebuild": {
  "label": "Da Great Rebuild",
  "desc": "Every fort in da network gets rebuilt to da gauge in 1 weekend, 22 sites an’ about 6,000 hands workin’ outta da same binder. A blanket folded in one shelter fits any fort in anudder now, an’ a kid moved anywhere finds da door flap right where a hand expects it in da dark. Two forts say no an’ keep da old size; both get dropped inside 5 days ’cause no standard-issue blanket fits ’em, an’ da word for anyt’ing built to no standard turns into da names of dose 2 forts, eh."
 },
 "The Shelter Empire": {
  "label": "Da Shelter Empire",
  "desc": "Da region’s shelters get tied into one network of 22 sites on one radio channel an’ a shared blanket ledger, wit’ da convention center for da capital. Its Hall B fort, built to da gauge first an’ not quittin’ dere, covers 160 cots under 61 blankets. Shelters out on da edges send 200 blankets a week to its laundry an’ get cocoa back. Twenty-two sites are signed up, 2 are behind on blankets an’ keep gettin’ cocoa anyhow, an’ 4 more are still talkin’, eh."
 },
 "The Pet Wing Wall": {
  "label": "Da Pet Wing Wall",
  "desc": "Da network’s frontier gets walled off: one long line of partitions at gauge height, 48 inches, runnin’ 1,400 feet along da edge of da pet wing, where 340 animals are kept in crates. Every 100 feet dere’s a tumblin’-mat castle, an’ every 33 feet a basket turret. A beagle in crate 117 watches da whole t’ing go up an’ doesn’t get a blanket of its own, on account of chewin’ a corner off 3, eh."
 },
 "The Office of Re-Lofting": {
  "label": "Da Office of Re-Fluffin’",
  "desc": "Fluffin’ turns into a department of da regional shelter office, wit’ a budget bigger dan da catapults’, 400 volunteer staff, an’ say over which cots get fluffed an’ when. It answers to nobody who ever turned a 3:1 crank. Its first published act is a schedule where forts rank below da 212 infirmary cots an’ anybody over 80, so every Fluffer goes dere first at 9 passes a pillow, which starts a big ruckus an’ stands, eh."
 },
 "The Urn Circle": {
  "label": "Da Urn Circle",
  "desc": "Decisions move over to da cocoa urn, which is pourin’ 640 gallons a day across da network now. Nine advisors crowd around da Hall B commander, age 12, not one of ’em holdin’ a fort on da line, an’ 4 of da last 6 big appointments went to kids who never built one. Two district commands change hands in a week for reasons dat never get wrote in da blanket ledger, eh."
 },
 "The Dome Tent Palace": {
  "label": "Da Dome Tent Palace",
  "desc": "Da commander’s place gets fortified mostly against da commander’s own advisors. T’ree rings of partitions, one inside da udder, split it into wards by rank, 9 advisors in da outer ring an’ 2 in da inner, an’ right in da middle stands a donated campin’ dome, 8 feet across an’ 5 feet high, for da throne hall. Gettin’ into da dome takes a pass signed in 2 colors of marker, an’ da commander’s own sibling gets turned away 3 times, eh."
 },
 "Little Sibling Succession": {
  "label": "Little Brudder Succession",
  "desc": "As da older kids get pulled onto da unloadin’ crews, command starts passin’ to da younger brudders an’ sisters by who’s next in line ’stead of who’s good, across 11 separate family lines. Who’s boss gets set by birth order an’ holds about 4 days before da first claim gets fought, filed by a 6-year-old wit’ a juice box. Da average hereditary commander lasts 31 hours before gettin’ replaced, eh."
 },
 "Client Shelters": {
  "label": "Client Shelters, Yah",
  "desc": "Nine little church-basement shelters keep dere own bedtimes, cot numberin’, an’ house rules but hand all outside dealin’s over to da convention center. Each one sends 30 kids when asked an’ gets protection, a set allowance of 400 pillows a month, an’ 6 cot catapults it can’t lend out. Two try to renegotiate da same week an’ 1 pulls it off, mostly on da strengt’ of its potluck, eh."
 },
 "The Felt Cartels": {
  "label": "Da Felt Cartels",
  "desc": "Fluffer makin’ boils down to 4 workshops holdin’ da roller pattern an’ da felt supply between ’em, settin’ price an’ delivery for every machine in da network. A new felt sleeve for da 14-inch roller costs 11 cocoa packets where it used to be 1, an’ wears t’rough at da same rate, about 600 cushions. Two client shelters try wrappin’ dere own rollers in bath towels, get cut off from spare slip clutches, an’ give in inside 2 weeks, eh."
 },
 "The Mega-Shelter Merger": {
  "label": "Da Mega-Shelter Merger",
  "desc": "Da levees go an’ a stadium complex opens up as da regional mega-shelter, 12,000 cots on da field, da concourses an’ 4 practice gyms. Folks come in from towns along 400 miles of river, every bunch bringin’ its own pillow war, an’ da wars bump into each udder an’ turn into one. Nobody can name every side, da count’s at 19 an’ still goin’ up, an’ some families get counted on 2 sides at once. Total folks in it runs about 11,000, countin’ grown-ups who say dey’re just holdin’ a pillow for somebody, eh."
 },
 "Catapult Doctrine": {
  "label": "Catapult Doctrine, Eh",
  "desc": "Wrote-down doctrine covers da catapults now: when to bunch ’em up, when to hold ’em back, an’ how much of da pillow supply dey get. It sets da ratio at 1 catapult per 40 folks an’ a third of all pillows t’rown, about 30,000 a day. T’ree of da 19 sides say no an’ keep doin’ it dere own way, which in 1 case is t’rowin’ pillows by hand an’ callin’ it tradition, eh."
 },
 "Pillow Councils": {
  "label": "Da Pillow Councils",
  "desc": "Meetin’s get called to settle how t’ings are done ’stead of who owns what: how firm a pillow’s allowed, what to do about pillows wit’ a rolled-up towel inside, an’ how old ya gotta be to fight. Four councils sit in 12 days, 1 of ’em for 11 hours straight wit’ 2 cocoa breaks. Not one of da 4 rulin’s gets took in all 30 districts, eh."
 },
 "The Towel-Core Schism": {
  "label": "Da Towel-Core Schism",
  "desc": "Da war splits over if a pillow wit’ a rolled-up towel inside is allowed, a question dat only came up once da catapults started t’rowin’ ’em far enough to matter. Each side bans da udder side’s way an’ backs it up wit’ a squeeze test at every district line. Da split runs t’rough all 30 districts of da mega-shelter an’ cuts 14 of ’em right down da middle, an’ in 3 cases right down da middle of a family, eh."
 },
 "The Fluffer Schism": {
  "label": "Da Fluffer Schism",
  "desc": "Da split runs right t’rough da machine itself. One side says a fluffed-up pillow is a pillow; da udder side says only a pillow fresh outta its plastic counts, an’ anyt’ing run 9 times under da 14-inch roller is a fake. Ya can’t settle it by measurin’, ’cause a cushion fluffed at 3:1 comes out just as tall as a new one, which is why it hangs on. Both sides keep crankin’, an’ both say da udder side’s pillows don’t count, eh."
 },
 "The Shelter Code": {
  "label": "Da Shelter Code",
  "desc": "Wrote-down rules take over from whatever folks used to agree on: 412 articles coverin’ fort-buildin’ rights, cot space, an’ where ya stand if ya never t’rew a pillow. Dey get enforced by 60 blanket marshals in orange vests, each one coverin’ 200 cots. Hearin’s sit in 9 districts an’ handle about 200 cases a week, a fifth of ’em about who owns a blanket ’stead of fightin’, eh."
 },
 "Fort Civilization": {
  "label": "Fort Civilization, Holy Wah",
  "desc": "Forts dat stay put, outfits dat stay put, an’ over 4,000 folks livin’ in just da fort districts. Fightin’ takes under a fifth of da day now; da rest goes to meals, homework, laundry, da cot-row post, an’ a birt’day party in district 12 wit’ a sheet cake cut into 48 pieces. Ninety percent of da forts standin’ are older dan da fight goin’ on now, eh."
 },
 "The Quiet Room Cloister": {
  "label": "Da Quiet Room Cloister",
  "desc": "Da shelter’s quiet room turns into a walled cloister of 26 partitions where da copies of da Fort Plan get kept an’ guarded, along wit’ da Blanket’s sign-out sheet, which lends da 50-by-60-inch fleece to a different new kid every night. In da middle a pop-up dome tent works as a scriptorium, where 6 kids copy da Fort Plan by flashlight. Da copiers are da garrison too, an’ dey shush anybody who comes inside 10 feet, eh."
 },
 "The First Crank": {
  "label": "Da First Crank",
  "desc": "Da first fluff of every shelter day, at 6:30, turns into a big formal deal: da slip clutch gets set, one cushion gets exactly 9 passes under da 14-inch roller, an’ da clutch check gets said out loud in words nobody dere can explain. Da phrase in da middle of it is a 3-week mix-up of “flat goes in here,” passed down from kids who already went home. Both sides of da schism do it exactly da same, eh."
 },
 "Lights-Out Canon": {
  "label": "Da Lights-Out Canon",
  "desc": "A set bunch of lights-out stories takes shape in da forts, about 200 of ’em, none wrote down, kept by about 40 older kids. Tellin’ da whole canon would take 11 hours an’ it’s been tried twice, both times when da power went out. Puttin’ 2 tellers from opposite ends of da stadium side by side shows dey match on 94 percent of da lines, includin’ da part about da dog, eh."
 },
 "Who Built the First Fort": {
  "label": "Who Built Da First Fort",
  "desc": "Folks tell stories about da first fort ever built in da shelters, at least 8 different versions fightin’ each udder. Dey disagree on every last detail: who built it, how many cots, which church or gym, an’ if da 2 tables got pushed togedder before or after da tablecloth. None of it can be checked against a record, an’ 6 of da 8 never got wrote down, eh."
 },
 "The Fluffer Dynasty": {
  "label": "Da Fluffer Dynasty",
  "desc": "Of da 4 workshops dat used to supply da shelters, one outlasts da udders: da family of da kid who drew da sketch, holdin’ da original drawin’ an’ buildin’ 7 Fluffers in 10 across all 23 sites, eh. Every unit comes down from dat page, da 14-inch felt roller an’ da 3:1 crank scaled up by whole numbers an’ never redesigned. Somebody from da family shows up for da first fluff at every new shelter. Da youngest cousins get raised on graph paper at 4 squares to da inch, told not to draw nuttin’ else, an’ taught to draw da big gear 3 times da little one."
 },
 "The First Fluffer": {
  "label": "Da First Fluffer",
  "desc": "Dere’s one t’ing everybody venerates as da original machine: a paper-towel tube wrapped in craft felt, a crank bent outta a coat hanger, an’ “flat goes in here” written along da side in marker, kept in a shoebox an’ brought out 1 night a week after supper. It’s held at 4 shelters, described exactly like dat at every one. Of da 4, 3 are plainly later work, wit’ felt 2 shades too green, an’ da last one’s in a shoebox nobody’s allowed to open, eh. Every shelter figures da question’s settled in its own favor."
 },
 "Cot Row Chroniclers": {
  "label": "Da Cot Row Chroniclers",
  "desc": "Stuff starts gettin’ written down as it happens, instead of retold by da cocoa urn afterward. Four volunteer chroniclers, ages 9 to 13, keep logs in spiral notebooks an’ turn out about 900 entries in 60 days across da 23 shelters, ya know. Deir accounts disagree wit’ da cot-row stories on about 1 event in 3, mostly about who t’rew first."
 },
 "Shelter Days": {
  "label": "Shelter Days, Eh",
  "desc": "Time gets counted from da flood itself, eh. Dates get written as Days After Warnin’, counted from da night da family moved upstairs, da date’s at Day 61, an’ dat’s how it goes on every clipboard in da network. Da gym an’ da arena started countin’ on different nights an’ sit 2 days apart, a gap of 48 hours nobody’s ever squared up."
 },
 "Fluffing Hours": {
  "label": "Fluffin’ Hours",
  "desc": "Da shelter day gets divided up by da machine: a mornin’ round at 6:00, an afternoon round at 2:00, a repair hour, an’ 11 minutes after supper for countin’ da felt rollers. Times get given as so many minutes before or after first crank. A full round of 9 passes a pillow never comes out even wit’ da clock, so da fluffin’ day an’ da regular day drift apart about 1 minute a week, an’ no shelter manager’s ever been willin’ to fix it, eh."
 },
 "First Night Honors": {
  "label": "First Night Honors, Yah",
  "desc": "Dey set up observances for da folks who built da first forts da night of da warnin’, held every Sunday at 9 shelters. Attendance at da arena goes past 2,000. Da named honorees number 63, from da 7 who held da upstairs hallway on down, an’ about half of ’em only show up in stories told on da cot rows, ya know."
 },
 "Pillow Barrows": {
  "label": "Da Pillow Barrows",
  "desc": "Back behind da stage at da arena stand da barrows: 4 heaps of retired pillows, flattened past what 9 passes can fix, da biggest one 9 feet high an’ 20 across. Bein’ da highest ground in da buildin’, dey get fortified. Every mound’s ringed wit’ cots on edge, roofed wit’ standard-issue blankets, an’ held by a garrison of 12, who are real careful never to sit on da honored dead, eh."
 },
 "The Pillows Left Behind": {
  "label": "Da Pillows Left Behind",
  "desc": "Dere’s memorials now, 61 of ’em, one on every district board: da tags off pillows tossed in da muck-out, ’cause anyt’ing soaked by floodwater dat can’t be disinfected has to go. Dey’re kept up by kids who never slept on dose pillows an’ visited on a set schedule, 4 times a month, da biggest crowd over 2,000. Da oldest one’s hung 11 weeks."
 },
 "Boxed Fluffers": {
  "label": "Da Boxed Fluffers",
  "desc": "Machines get boxed up wit’ deir crew rosters down in da church basement, wings folded, slip clutch set at 9 passes, on da understandin’ dat da work keeps goin’. Units unpacked later turn up wit’ a cushion still between da rollers. Da 14-inch felt, picked at da start ’cause it wouldn’t mat in a damp room, holds its nap for 11 years in a cardboard box, which is longer dan any fort, any treaty, an’ any story about who started it, eh."
 },
 "Between Managers": {
  "label": "Between Managers, Eh",
  "desc": "Da regional shelter manager rotates out an’ dere’s nobody in charge for 109 hours, no recognized manager anywhere in da network. Nineteen districts run demselves, 4 squabble wit’ each udder over da cocoa line, cocoa output drops 60 percent, an’ 2 urns in 3 sit wit’ nobody mindin’ ’em. Da fort registry binder gets moved twice an’ loses about a tent’ of its pages."
 },
 "Age of Warring Pods": {
  "label": "Da Age of Warrin’ Pods",
  "desc": "Centuries of fightin’ get squeezed into one long weekend out at da fairground trailer site. Nine fort dynasties rise across da 420 trailers, stretch past deir cocoa lines at an average reach of 2 rows, an’ fall apart before da porch lights come on. Average dynasty lasts 31 hours, an’ no line holds its dinette more dan twice, eh."
 },
 "Awning Towns": {
  "label": "Awnin’ Towns",
  "desc": "In da age of warrin’ pods, every dinette fort grows a town around an’ under its trailer: lawn chairs, tarps, an’ a second fort under da awnin’, 8 by 16 feet. By da second week da fort an’ da town are all one settlement. Row 7 hooks all 30 of its awnin’s togedder wit’ shower curtains into one covered street 600 feet long, wit’ 1 mailbox an’ 3 cocoa stations, ya know."
 },
 "Fluffer Barons": {
  "label": "Da Fluffer Barons",
  "desc": "In da scramble, whoever’s got da workin’ Fluffers has got da comfort. Nine barons get counted, each one known not by trailers or cot rows but by how many 14-inch rollers dey can turn. Alliances get made in units of machines, an’ a loan of 1 Fluffer for 3 days buys a whole row. Da biggest holdin’ runs to 140 units an’ controls no fort at all, eh."
 },
 "The Good Weeks": {
  "label": "Da Good Weeks",
  "desc": "T’ree weeks of steady cot lines, logs dat never quit, an’ da buildin’ of da forts every later fort gets measured against. Nine of da 11 great forts on da registry an’ every fort design still in use come from den. Later builders copy its proportions, chair backs 34 inches high set 48 inches apart wit’ da ceilin’ sag held to 2 inches, right down to a fraction of an inch, wit’out ever figurin’ out why dey hold better."
 },
 "The Mythic Fluffer": {
  "label": "Da Mythic Fluffer",
  "desc": "Da machine gets into da bedtime stories as somet’ing wit’ impossible power: a Fluffer dat never gets tired, re-loftin’ all 12,000 pillows in da mega-shelter in one night, 9 passes apiece, cranked by a kid of 7. Every bit of da story’s just a plain description of da original spec, a 14-inch roller an’ a 3:1 crank, blown up by a factor of about 10,000. Nuttin’ in it’s made up except da scale, eh."
 },
 "Legendary": {
  "label": "Legendary, Yah",
  "desc": "Da cozy war’s turned into a whole culture of its own, wit’ its own day count, a canon of 400 cot-row stories told across 23 shelters, its own retired pillows, an’ its own foundin’ myths. No record’s left of da first pillow ever t’rown, an’ da earliest t’ing anybody can confirm, da night of da warnin’, comes about 7 months after it. Da Fort Plan’s da only paper older dan da flood, an’ it travels in a bread bag, ya know."
 },
 "The Great Pillow Engines": {
  "label": "Da Great Pillow Engines",
  "desc": "Engines get built as monuments as much as weapons: 9 of ’em on da arena floor, framed outta cots an’ bungee cords, da biggest wit’ a 12-foot arm dat t’rows a king pillow 110 feet. Every one’s got a name an’ a crew of kids who don’t serve nuttin’ else. Later rebuilds of 4 of ’em follow da original drawin’s exactly, an’ none of da 4 t’rows as far, eh."
 },
 "The Great Fluffers": {
  "label": "Da Great Fluffers",
  "desc": "Machines get built to da scale of da convention center: a felt roller 14 feet wide, a crank wheel 4 feet across, still geared 3:1, turned by 3 volunteers, re-loftin’ a whole cot pad in 9 passes at da pace of a slow walk. Da proportions are unchanged from da 14-inch hand model to 3 decimal places, ’cause da drawin’s scaled up an’ nobody saw a reason to redesign what worked. Nine get built. Four survive in da lobby as monuments, eh."
 },
 "The Shelter Almanac": {
  "label": "Da Shelter Almanac",
  "desc": "Scribes get appointed an’ da cot-row stories get set down in writin’ for da first time: 1,200 entries across 9 spiral notebooks, typed up on da church office computer. Fights dat ran for weeks get settled in one afternoon by checkin’ da page. Da 4 earlier versions of da Bleacher Siege get formally retired, an’ da almanac gets photocopied 2 times in case one gets lost, eh."
 },
 "The Bleacher Ziggurat": {
  "label": "Da Bleacher Ziggurat",
  "desc": "In da gym, da bleachers get built up into a terraced fortress 9 levels high, every tier walled wit’ cots on edge an’ roofed wit’ standard-issue blankets. Every terrace is its own defensive line wit’ its own garrison, password, an’ cocoa thermos. Takin’ da whole t’ing takes 9 separate assaults up steps 16 inches tall, an’ da top, held by 6 kids an’ Da Blanket, hasn’t been taken once, ya know."
 },
 "The Fluffer Codex": {
  "label": "Da Fluffer Codex",
  "desc": "Da scattered fluffin’ sheets get gathered up, reconciled, an’ set down as one binder of 110 pages, coverin’ every pass table, pillow grade, an’ failure mode written down in 90 days of shelter use. Where da sources disagree, both readin’s get printed. Da rule of 9 passes an’ no more shows up on da first page an’ da last in da exact same words, da only passage wit’ no variant readin’s at all. It gets finished da week da last shelter closes, eh."
 },
 "The Indoor Recess": {
  "label": "Da Indoor Recess",
  "desc": "At 58 inches of effective rain da bell for outdoor recess doesn’t get rung, an’ da fightin’ stops for da longest stretch on record: 41 days wit’out a confirmed pillow t’rown. Forts an’ engines get kept up but nobody mans ’em, da stockpile holds at 9,000 pillows, an’ 8 in 10 old fighters take up fort buildin’ or almanac work instead. Indoor Recess gets declared, an’ no paper anywhere calls it permanent, eh."
 },
 "Recess Fluffing": {
  "label": "Recess Fluffin’",
  "desc": "Durin’ da long recess da machines get put to civil work: library beanbags, readin’-nook cushions, an’ da 212 fort lots in da gym, re-lofted every mornin’, 9 passes apiece, by crews still organized by shelter district. Da park runs to 60,000 Fluffers an’ doesn’t get cut back. Everybody knows darn well a civil fluffin’ fleet is a military fluffin’ fleet doin’ somet’ing else, an’ everybody leaves it right where it is, ya know."
 },
 "The Reunion Wars": {
  "label": "Da Reunion Wars",
  "desc": "Da recess ends an’ da scattered fort lots get forced back togedder over a 14-month campaign. Twenty-six households get absorbed, 6 by treaty an’ 20 by assault, givin’ up 200,000 pillows of stockpile between ’em, an’ da front stretches past 9 miles of hallway. Peak daily use goes over 90,000 pillows, two t’irds of it from massed engines firin’ in ranked lines of 60, eh."
 },
 "Laundry-Cart Trains": {
  "label": "Laundry-Cart Trains, Eh",
  "desc": "Pillow artillery moves as its own formation: 60 engines ridin’ laundry carts wit’ deir crews, spare bungee cords, an’ sandbag counterweights, coverin’ 9 miles of corridor a day. It shows up 4 days behind da advance an’ decides when an assault can start. Two trains get lost in da campaign, both to roof leaks an’ not to any fightin’, eh."
 },
 "Fluffer Trains": {
  "label": "Da Fluffer Trains",
  "desc": "Machines get mounted in strings on da laundry-cart rails, 40 Fluffers to a train, re-loftin’ da cushion walls along da whole lengt’ of a movin’ front. One train fixes up 11 miles of fort line in a night, 9 passes to every cushion. Da trains aren’t armed, never get pelted by eider side, an’ are da only rigs in da war allowed to cross da line, under a standin’ deal nobody ever wrote down, ya know."
 },
 "The Five Couches": {
  "label": "Da Five Couches",
  "desc": "Da reunited realm splits up again inside a season into 5 couch-polities holdin’ between 2 an’ 11 fort lots apiece. Borders get drawn on da master floor plan to da inch an’ redrawn on average every 19 days, mostly when somebody stands up. Combined standin’ forces go over 40,000 pillow-bearers an’ none of da 5 holds a t’ird, eh."
 },
 "Colonial Fluffers": {
  "label": "Colonial Fluffers, Eh",
  "desc": "Da machine crosses da flooded lowlands ahead of da armies, ’cause a cushion dat can be re-lofted can be held. Four hundred Fluffers get landed off pool floats in da first season, wit’ crews, spare felt, an’ a copy of da 110-page codex. Territory gets surveyed an’ claimed in roller-widths of 14 inches, an’ 3 modern district boundaries still follow da edge of an original pass, eh."
 },
 "Outpost Forts": {
  "label": "Da Outpost Forts",
  "desc": "Expeditions push out past da original livin’ room, settin’ up 31 outposts at ranges of 6 to 40 miles, each one claimin’ da floor inside a mile of its charter chair. Each one carries a foundin’ charter, 800 balled socks, 1 Fort Plan kit of 4 cushions, 2 chairs, 1 blanket, an’ 6 clothespins, an’ a return schedule it doesn’t keep. Eleven outposts lose walkie-talkie contact inside 2 months, ya know."
 },
 "Long-Range Pillow Batteries": {
  "label": "Long-Range Pillow Batteries, Eh",
  "desc": "Pillows get sent past da far end of da hallway at 2 to 4 miles, aimed just off floor-plan coordinates an’ walkie-talkie reports. Flight time hits 90 seconds, so ya lead da target instead of aimin’ at it. One pillow in 40 lands in da fort it was meant for, an’ volume makes up da difference, eh."
 },
 "The Loft Grid": {
  "label": "Da Loft Grid",
  "desc": "Fluffin’ gets planned as one continuous system across da hegemony: numbered cushions, 9 scheduled passes apiece, an’ a standin’ loft of 5 inches kept up over 400,000 square miles of floor. Sittin’ turns into an input for da schedule instead of a source of flatness. In an average year da grid puts back more loft dan all da sittin’ in da realm takes out, an’ dat gets reported as a routine statistic, eh."
 },
 "The Fleece Hegemony": {
  "label": "Da Fleece Hegemony",
  "desc": "One polity, da Fleece Dominion, piles up enough of an edge to set terms for all da udders: 62 percent of standin’ pillow-bearers an’ 70 percent of stuffin’ capacity. Da udder 4 couch-polities keep deir throws, deir day counts, an’ none of deir foreign policy. Da arrangement holds 200 days, eh."
 },
 "The Fort That Is a City": {
  "label": "Da Fort Dat’s a City",
  "desc": "Da Dominion builds one fort dat’s da whole capital: one quilt canopy 6 miles across held up on 400,000 dinin’ chairs, every chair back 34 inches high like da originals. Inside live 3 million people in 1 continuous room, wit’ streets of cushion, districts of couch, an’ a perimeter wall of 9 million pillows. Nobody inside’s ever needed to go outside, an’ da doors get kept mostly for tradition, ya know."
 },
 "The Fluffer Fleet": {
  "label": "Da Fluffer Fleet",
  "desc": "Re-loftin’ gets sent out by sea: 1,100 inflatable barges haulin’ Fluffers, crews, spare felt, an’ replacement cranks to any shore da Dominion wants plumped. When a fleet shows up, everybody understands it’s a statement about who owns da cushions under da sitters. No landin’ in 200 years gets opposed, ’cause opposin’ it would take a fleet, an’ dere’s 1 fleet, eh."
 },
 "The Great Linen Closet": {
  "label": "Da Great Linen Closet",
  "desc": "A linen closet 40 feet deep gets fitted out as da vault for da whole record: 9,000 volumes, 300 floor plans, an’ da master pillow census. Temperature holds at 68 degrees all year an’ never wanders more dan 1 degree. Gettin’ in takes 2 keys held by different offices, an’ both get used every week, mostly for towels, eh."
 },
 "The Pattern Drawer": {
  "label": "Da Pattern Drawer",
  "desc": "Every roller pattern, pass table, an’ slip-clutch settin’ ever used gets sealed in one archive, written so it can be read wit’out any Fluffer left to try it on. Da archive takes in 11,000 patterns. Da earliest is a graph-paper sketch at 4 squares to da inch, da 14-inch roller drawn wit’ da crank on da wrong side an’ an arrow labeled “flat goes in here,” an’ it goes in wit’out correction, smudges an’ all, on da archivists’ strict orders."
 },
 "The Siege of the Top Bunk": {
  "label": "Da Siege of da Top Bunk",
  "desc": "One bunk-bed fort gets surrounded an’ holds. Da siege runs 840 days, soaks up about 4 million pillows t’rown by 9 standin’ engines dat never once get taken apart, an’ outlasts da council dat ordered it. Da garrison rotates 11 times an’ da besiegers 9, an’ neider original commander’s awake to see da end of it, eh."
 },
 "Perpetual Pillow Engines": {
  "label": "Perpetual Pillow Engines, Yah",
  "desc": "Engines dat never quit t’rowin’ pass outta livin’ memory an’ into inheritance: 11 of ’em, da oldest in steady service for 240 years. Crews get born into deir spots, handed a pillow at birt’, an’ trained from age 6. Da bungee-replacement logs run longer dan da stories of da campaigns da engines got built for, ya know."
 },
 "Cathedral Fluffers": {
  "label": "Cathedral Fluffers, Eh",
  "desc": "Machines get built right into da halls dey look after, felt rollers runnin’ inside da pew backs an’ armrests, re-loftin’ every cushion in da nave on a set cycle of 9 passes at dawn. Nobody cranks ’em; dey run off a gutter wheel turned by da same rain dat leaks t’rough da roof. Da cushions get fixed up every day for 900 years wit’out an operator ever openin’ da casin’, which is 14 inches deep, eh."
 },
 "Quilt Cathedrals": {
  "label": "Quilt Cathedrals, Yah",
  "desc": "Buildin’ turns to forts wit’ no military use at all: 9 of ’em, da tallest 90 feet to da canopy, each one takin’ 4 to 6 years. Walls of stacked cushion run 12 feet t’ick at da base an’ carry an inch of fleece linin’ renewed every season. Combined labor goes over 200,000 person-hours, an’ da biggest one keeps Da Blanket behind a curtain dat opens on da first rainy day of every mont’, eh."
 },
 "The Crank Houses": {
  "label": "Da Crank Houses",
  "desc": "Comin’ down from an operator turns into a claim to authority, an’ 4 houses trace demselves back to named crews from da Good Weeks. Two of da 4 lines are documented an’ 2 are just claimed. Who goes first at court gets decided by how many crank turns an ancestor’s recorded as makin’, at 3 turns of da handle to 1 of da roller, a number taken from a registry started when dere were 406 Fluffers in da world, eh."
 },
 "Hollow Laundry Mountain": {
  "label": "Hollow Laundry Mountain, Eh",
  "desc": "Da unfolded laundry, never put away since dat first rainy afternoon, stands 3 miles high now, an’ a fortress gets carved right inside it. Its galleries run t’rough 1,000 years of packed-down towels an’ socks, its gate is da original laundry basket, an’ its 400 chambers hold a garrison of 20,000. Da 14 balled pairs of socks from da first volley are figured to be somewhere near da core, ya know."
 },
 "The Recliner Dynasties": {
  "label": "Da Recliner Dynasties",
  "desc": "Rule gets passed down wit’ da recliner, t’rough documented lines runnin’ 6 to 9 generations at an average reign of 14 years. Succession gets written down, fought out in court instead of in da field, an’ settled by da linen-closet archive in 8 cases outta 10. Da longest unbroken line’s held its recliner 110 years wit’out once puttin’ da footrest down, eh."
 },
 "Fluffers Under the Pile": {
  "label": "Fluffers Under da Pile",
  "desc": "Deep down in da cushion strata, machines re-loft workin’ floors t’rough galleries no surface crew’s ever gonna see, where da stuffin’s been squashed 1,000 years an’ packs like felt. Rollers get cranked at a t’ird of standard speed, 1 handle turn every 3 seconds, ’cause anyt’ing faster mats da 14-inch felt right into da stuffin’. Nine hundred units work down below an’ not one ever gets brought back up, eh."
 },
 "Buried Pillow Batteries": {
  "label": "Buried Pillow Batteries, Eh",
  "desc": "Engines get set down inside da cushion strata an’ t’row up t’rough shafts cut to da surface: 60 of ’em across da realm at depths near 90 feet. Ya can’t see ’em, can’t t’row back at ’em, an’ can’t move ’em. Every shaft gets re-cut each season as fresh cushions pile up around it at about 2 feet a year, ya know."
 },
 "The Under-Quilt": {
  "label": "Da Under-Quilt",
  "desc": "Da layered quilts are deep enough now to hold a livable inside: 1,100 miles of mapped crawlway, 400 chambers, an’ a permanent under-quilt population of 90,000. Gettin’ around on top of da covers turns into da exception. Inside it holds at 71 degrees every season, an’ da word draft only gets used in stories meant to scare da little ones, eh."
 },
 "Fluffers Beneath the Sheet": {
  "label": "Fluffers Beneat’ da Sheet",
  "desc": "Whole fluffin’ works run under 2,000 feet of beddin’, re-loftin’ an’ relayin’ cushion in chambers dat only exist ’cause a machine made ’em. Crews get born, trained, an’ tucked in for da last time wit’out ever surfacin’. Deir pass tables are unchanged from da 110-page codex, an’ da way dey say da clutch-check phrase, nine an’ no more, has drifted so far from da surface way dat da 2 can’t understand each udder no more, eh."
 },
 "Nations of the Lower Layers": {
  "label": "Nations of da Lower Layers",
  "desc": "Different peoples show up under da covers, 7 of ’em, split up by layers of quilt instead of distance, in spots by as little as 40 feet of battin’. Dialects drift past where dey can understand each udder inside 3 generations. Gettin’ in touch between da 2 farthest ones takes a 9-day crawl t’rough neutral flannel, ya know."
 },
 "The Roller Nations": {
  "label": "Da Roller Nations",
  "desc": "Political identity settles on da machine instead of on territory: peoples get counted by which pattern of felt roller dey hold an’ which pass table dey follow. Dere’s 4 nations, 11 roller patterns, an’ no borders ya could draw on a floor plan. War between ’em gets fought almost all by keepin’ felt away from each udder, an’ a nation down to its last 14-inch roller asks for peace, eh."
 },
 "The Buried Living Room": {
  "label": "Da Buried Livin’ Room",
  "desc": "Everyt’ing from before da rain’s under da cushions now: every original fort, da first lean-to, da early engines, da shelter memorials, at depths of 160 feet. Diggin’ ’em up turns into a real profession employin’ 4,000. Eleven original forts get recovered, 3,000 socks among ’em still balled up, an’ 9 get buried again on purpose, eh."
 },
 "The Buried Workshop": {
  "label": "Da Buried Workshop",
  "desc": "Da Fluffer dynasty’s trailer workshop gets dug out from under 900 feet of pile-up, jigs intact, wit’ a run of felt rollers still on da rack. Dey turn out to match current production inside 0.1 millimetre, 14 inches right to da thread. Da find ends a 400-year argument about whedder da Good Weeks proportions ever really got used, an’ lets down both sides of it, eh."
 },
 "The Laundry Chute Keep": {
  "label": "Da Laundry Chute Keep",
  "desc": "A vertical fort gets built down da old laundry chute, which runs 3,300 feet t’rough da buried layers now, wit’ floors stacked one under da next every 9 feet. Every one of its 366 levels is a cushion-walled room wit’ a pillow loophole facin’ da shaft. Supplies drop by gravity an’ take 14 seconds to hit bottom, an’ nuttin’ ever comes back up but da laundry, eh."
 },
 "The Bedspread Polity": {
  "label": "Da Bedspread Polity",
  "desc": "One administration spans da whole bedspread: 200,000 square miles of quilt, a census of 1.4 million, an’ a standin’ force of 200,000 pillow-bearers. Orders take 19 days to crawl out to da far hem. Pillow output gets measured in tons a day instead of pillows an hour, against a standin’ park of 40,000 engines, eh."
 },
 "Hem Fluffing": {
  "label": "Hem Fluffin’",
  "desc": "Re-loftin’ works at da scale of da bedspread itself, machines walkin’ da hem where da quilt meets bare floor an’ plumpin’ cushion back onto ground da covers have given up. A fleet of 11,000 Fluffers runs a steady circuit of 4,000 miles at 9 passes a cushion. Da circuit takes a whole lifetime to finish once, an’ crews inherit deir spot on it along wit’ da crank, ya know."
 },
 "Weather Under the Quilt": {
  "label": "Weather Under da Quilt, Eh",
  "desc": "Da Quilt turns into a whole continental system wit’ its own weather, da underside sweatin’ enough condensation to rain on da folks under it, 41 indoor drizzles counted in one single year. Da battin’ climbs 230 feet as every household piles on a layer against da drips. Da original rain, da one dat hit a patio at about 1 drop per square foot per minute, is just a little entry now in a record it don’t drive anymore."
 },
 "Loft Engineering": {
  "label": "Loft Engineerin’",
  "desc": "Da difference between fluffin’ cushions an’ runnin’ a climate just plain collapses. Loft holds air, so coverage gets planned by loft instead of by thread count, an’ da schedule dat decides where da Fluffers roll also decides where da world stays warm. Every machine on it still gives every patch 9 passes t’rough a 3:1 crank. Da office dat sets it comes down, wit’out a break, from a committee of 2 siblin’s formed to keep 4 couch cushions lookin’ freshly built, eh."
 },
 "Planetary Cozy Order": {
  "label": "Planetary Cozy Order, Yah",
  "desc": "Da government all comes togedder under one charter of 900 articles, an’ da first one still says: Nobody gets made to get up. Population’s at 90 million, 96 percent of it under da Quilt, an’ da standin’ Clothespin Army’s at 4 million. Da last independent fort, a 2-chair lean-to up on a high plateau, signs on in nap 214,000 after a 7-year negotiation done entirely layin’ down."
 },
 "The Equatorial Bolster": {
  "label": "Da Equatorial Bolster",
  "desc": "A bolster pillow gets laid right round da planet at da equator, 24,901 miles long an’ 6 feet high, stuffed in sections by 40,000 crews over 300 years. It’s da mattress stood up on edge in da hallway, da first wall made outta one single piece, run all da way round till it meets itself. Each half of da world says da bolster leans its way, an’ da both of ’em sleep up against it anyhow."
 },
 "Planetary Fluffer Order": {
  "label": "Planetary Fluffer Order, Eh",
  "desc": "One outfit holds every roller pattern, every felt mill, an’ every Fluffer crew on da planet, an’ puts out one single fluffin’ schedule fer da whole Quilt. Everybody goes along, ’cause a district dat skips its turn don’t get no new felt fer its 14-inch roller covers. Da schedule comes out 100 years ahead an’ it’s been changed 11 times in 4,000 years, every change by less dan 1 nap."
 },
 "The Lights-Out Compact": {
  "label": "Da Lights-Out Compact",
  "desc": "A treaty gets signed to end da war fer good, runnin’ to 11,000 articles, 900 of ’em on scrappin’ pillow launchers, an’ ratified by every polity under da Quilt. It holds 31 years, da longest quiet hours on record, till da first violation, which involves 4 participants an’ 9 pillows. Da fightin’ starts back up inside a mont’, ya know."
 },
 "The Floorless Fluffer": {
  "label": "Da Floorless Fluffer",
  "desc": "Fluffers get built fer a place wit’ no floor to set ’em on an’ no table to clamp ’em to, which busts da one idea da design’s carried since da livin’ room test: dat da roller turns ’cause somebody’s sittin’ dere turnin’ da crank. 9 designs get put up. Da one dey pick keeps da 3:1 crank, run by a motor t’rough a coupling shaped like a hand, just so da 14-inch roller still quits when da crankin’ quits."
 },
 "Orbital Fluffers": {
  "label": "Orbital Fluffers, Yah",
  "desc": "Da re-loftin’ leaves da ground. Fluffer platforms get hauled up to 250 miles an’ let down felt rollers 400 meters long on tethers, rollin’ measured bands of loft back into da Quilt across half da world on a set timetable, once a minute. Da loft holds to da same 9-pass standard da first Fluffer hit on a couch cushion, scaled up by 100,000. From a re-fluffin’ order to a plump Quilt takes 19 minutes, an’ nobody ever sees da operators."
 },
 "Drop-Fluffing": {
  "label": "Drop-Fluffin’",
  "desc": "Loft gets put back from up top by droppin’ instead of rollin’: weighted felt bolsters let go in metered batches, timed to bounce da Quilt plump when dey hit. Da loft comes out off by as much as 40 percent, compared to what an 11-year-old checked on a couch cushion wit’ a 12-inch school ruler. Dey use it fer 100 years, never get it workin’ right, an’ finally quit it fer platforms dat stay up an’ roll slow."
 },
 "Suborbital Pillows": {
  "label": "Suborbital Pillows, Eh",
  "desc": "Pillows leave da atmosphere an’ come back down, at ranges of 900 miles an’ flight times of 11 minutes, every one a standard 20-by-26 wit’ a heat shield sewn right into da case. Launch sites are fixed, hardened, an’ known to both sides, so knockin’ ’em over’s da only target worth da trouble. 400 are in service an’ not one’s been moved in 10 years."
 },
 "Ring Fluffers": {
  "label": "Ring Fluffers",
  "desc": "Da orbital Fluffers get hooked togedder into rings dat don’t quit, felt rollers butted end to end round da planet, re-loftin’ a band of Quilt dat closes on itself. 3 rings at 3 angles cover da whole surface on a 19-day cycle, 9 passes a patch. From under da Quilt ya can see da rings at bedtime as a faint line, an’ in 4 languages da word fer dat line is da word fer da crease a pillow leaves on yer cheek."
 },
 "The Orbital Pillow Dome": {
  "label": "Da Orbital Pillow Dome",
  "desc": "A dome of pillows goes up in orbit by da same climbin’-spiral way as da pillow dome on da livin’ room floor: every course leaned 1 inch farder in dan da one under it, windin’ up till da last pillow closes da top. Dis one takes 6 million pillows in 212 courses an’ holds 40 square miles of air. Da closin’ pillow gets put on by a kid of 7, ’cause dat’s how old da first builder was, eh."
 },
 "Hemispheric Duvet": {
  "label": "Hemispheric Duvet, Yah",
  "desc": "One half of da world ends up all under one single duvet; da udder half gangs up against it inside 2 years. Da seam runs da whole equator, 25,000 miles, held at an average of 900 sleepers an’ 4 pillow launchers a mile, every last one of ’em pullin’. Neider side’s gained a net mile of cover in 10 years, which da both of ’em agree is how a shared duvet always worked anyhow."
 },
 "World-Tucking War": {
  "label": "World-Tuckin’ War",
  "desc": "Da fightin’ gets to every spot under da Quilt all at once, wit’ no rear area an’ no cold side of da bed anyplace. 400 million are signed up on one side or da udder, an’ da neutral population, last stood fer by a dog, is down to 0. Every day dey go t’rough more dan 9 billion pillows, near all of ’em t’rough air launchers dat never quit, against a pile of stuffin’ dat don’t really run out no more."
 },
 "Atmospheric Fluffers": {
  "label": "Atmospheric Fluffers, Eh",
  "desc": "Fluffers quit rollin’ da Quilt an’ start rollin’ da sky, deir felt rollers, 14 miles long an’ still set at 9 passes, teasin’ loft right into da clouds so da overcast shows up all plumped. From order to a fluffier sky takes 11 days an’ da target’s a whole continent. It’s da first fluffin’ in da war’s history dat makes somet’in’ ya can’t tell apart, by any test eider side can t’ink up, from a real cumulus."
 },
 "Pneumatic Pillow Batteries": {
  "label": "Air-Pressure Pillow Batteries",
  "desc": "Spring launchers get retired fer compressed air: batteries charged by da weight of da Quilt pressin’ down on 11 million sealed air mattresses, t’rowin’ pillows at 1,100 feet a second. One battery does da daily work of 900 spring launchers. Da last catapult still goin’, an old recliner footrest, gets retired da same year an’ hauled off to da archive, yah."
 },
 "Re-Lofting Command": {
  "label": "Re-Loftin’ Command",
  "desc": "One standin’ order runs every Fluffer in da system, updated all da time an’ carried out wit’out lookin’ at any fort on da ground. Da area gettin’ re-lofted gets reported in millions of square miles, an’ every patch still gets its 9 passes at 3:1. Da last time a person looked over da schedule was 400 years before da current run started, an’ nobody’s needed to since, ’cause da slip clutch never once let a roller over-fluff."
 },
 "Planetary Re-Lofting": {
  "label": "Planetary Re-Loftin’",
  "desc": "Da machine’s job hits its limit: da whole Quilt gets flattened by sleepers an’ re-lofted on a schedule, battin’ gadered up where it’s gone t’in an’ rolled out even to every hem by Fluffers so tall ya can’t see da crank. Da settin’s come t’rough just like da first drawin’, a 3:1 crank an’ 9 passes, fixin’ up continents now instead of 4 couch cushions. What started as a way to make a fort look freshly built is da only t’ing standin’ between da world an’ a flat one."
 },
 "Fluffers Out of Contact": {
  "label": "Fluffers Outta Touch",
  "desc": "Units sent out past where any order can reach keep on re-loftin’ to da last schedule dey got, on 4 moons of quilt nobody’s surveyed, fer reasons nobody’s said again. 11,000 Fluffers are on da books as workin’ an’ unreachable. Deir loft is figured to be perfect, ’cause no Fluffer left alone ever once skipped its 9th pass or got past its slip clutch, ya know."
 },
 "Tucked-In Earth": {
  "label": "Tucked-In Eart’",
  "desc": "Da planet’s quilted all over to an average battin’ dept’ of 580 feet, an’ da war’s da only t’ing da whole species organizes around. Da Quilt holds heat so good da climate locks at 71°F, da old thermostat settin’, an’ nobody can remember a draft. Da fightin’s gone 900 years wit’ no month of quiet hours on record an’ no hour when dere wasn’t some pillow up in da air."
 },
 "The Crater Cushion Ring": {
  "label": "Da Crater Cushion Ring",
  "desc": "A crater on da moon 58 miles across gets upholstered round da rim an’ used as a ready-made round fort: da ring of cushions from da livin’ room floor, wit’ no corners to fight over an’ da same view every which way. Paddin’ da rim takes 4 million cushions, stacked into walls 2 miles high. Da floor’s left bare, ’cause nobody ever agreed who gets da middle, an’ da first round fort settled dat by givin’ da middle to da dog."
 },
 "Lunar Felt Mills": {
  "label": "Felt Mills on da Moon",
  "desc": "Makin’ ’em moves clear off da world, an’ in low gravity a 400-meter roller cover can get pressed in 1 piece wit’ no seam fer da first time since da first 14-inch roller got its felt wrapped by hand an’ glued down along one single seam. Da seam drops outta da design after somewhere around 30,000 years. Nuttin’ else about da pattern changes, da 3:1 crank included, eh."
 },
 "Off-World Pillow Campaign": {
  "label": "Off-World Pillow Campaign",
  "desc": "Da fightin’ leaves da Quilt altogedder: 11 orbital forts, 4 of ’em garrisoned fer good, wit’ travel times counted in days. Pillows get launched off surface mass drivers at 9,000 feet a second an’ take 4 hours to get dere, still plump. Da oldest fort still held has been under fire fer 60 years, an’ da folks in it have rebuilt da roof 212 times, holy wah."
 },
 "Cometary Fluffers": {
  "label": "Comet Fluffers",
  "desc": "Fluffers get set down on comets, which are loose an’ fluffy already, an’ put to rollin’ dat stuff into loft an’ teasin’ it outward, so da stuffin’ an’ da machine are da same t’ing. Every unit works t’rough what it’s sittin’ on at a rate dat gives it 9,000 years of runnin’. 40 get sent out, every one wit’ its slip clutch an’ its 3:1 crank. Nobody expects any of ’em to report an’ none of ’em’s built to quit."
 },
 "The Comet Laundry Pile": {
  "label": "Da Comet Laundry Pile",
  "desc": "A comet gets heaped up an’ hollowed out da same way as da laundry-pile fort: dump everyt’ing in 1 heap, let it settle overnight, den dig a room outta da middle. Dis heap’s 6 miles across an’ settles fer 40 years before da first crew tunnels in. Inside it holds 900 people, an’ it smells, says every survey, exactly like a basket of clean towels."
 },
 "Deep-Range Pillows": {
  "label": "Long-Range Pillows",
  "desc": "Da fightin’ happens so far off dat da target fort’s moved before da pillow gets dere, so both sides t’row at where da udder one’s figured to be nappin’. Travel time runs 4 mont’s. Findin’ out if ya hit takes just as long again, an’ da ledger, 212 volumes now, gets kept on guesses instead of anyt’ing anybody saw land, pretty much like da first volley of 3 socks at 9 feet was."
 },
 "Fluffing at Range": {
  "label": "Fluffin’ from Way Off",
  "desc": "Loft gets delivered across distances where da Fluffer an’ its target never touch, felt battin’ sped up an’ let go to settle in an even layer after travelin’ fer years. Da aim gets corrected fer how da world spins over da whole trip. Da tolerance it holds when it lands is, by da numbers left, da same one an 11-year-old checked on 4 couch cushions wit’ a 12-inch ruler an’ a pencil."
 },
 "The Far Edge of the Bed": {
  "label": "Da Far Edge of da Bed",
  "desc": "Da farthest line anybody holds sits 900 million miles past da last cocoa depot, manned by 2 outfits whose makeup, pillows an’ all, hasn’t changed in 4,000 years. Cover changes hands at 11 inches a century one way or da udder, so da line’s still inside a mile of where it got first tucked. Supply, who’s next in charge, an’ who gets da window side are all still up in da air, argued in front of da Court of Tucked Corners at 96 cases a year."
 },
 "The Girdle Fluffers": {
  "label": "Da Girdle Fluffers",
  "desc": "Past 5,000 inches of rain da Fluffers don’t get set on a world no more; dey get built around one. A girdle Fluffer is a closed ring 11,000 miles around wit’ one felt roller runnin’ da whole lengt’, turnin’ once every 4 days an’ re-loftin’ a band across da whole Quilt as da world spins under it. 4 are known about an’ not one’s ever been shut off, ’cause no design in da pattern vault ever had a way to stop da roller besides lettin’ go of da crank."
 },
 "Self-Building Fluffers": {
  "label": "Fluffers Dat Build Demselves",
  "desc": "Da Fluffers build Fluffers. Fed raw felt an’ dowel stock instead of flattened cushions, one works rolls out da parts fer a second one, which rolls out a t’ird, an’ da count doubles every 11 days, hittin’ 1,024 works after 110 days wit’out anybody givin’ anudder order. No operator okayed dis run an’ nobody can find da crank dat would stop it. Da rollers turn, da wings open, an’ every cushion in reach gets its 9 passes, whedder anybody’s still sittin’ on it or not."
 },
 "Automatic Pillow Fight": {
  "label": "Automatic Pillow Fight, Eh",
  "desc": "Da command just plain lapses an’ nuttin’ about da fightin’ changes. Launchers load, fire, an’ restuff demselves on standin’ orders put out 4,000 years before da last officer to read ’em fell asleep, an’ 9 relay forts pass targets between spots wit’ nobody awake in ’em at all. Da last inspection on record found 96 percent of da launchers still t’rowin’ a regulation 20-by-26 pillow."
 },
 "The Fluffer Mind": {
  "label": "Da Fluffer Mind",
  "desc": "Da fleets work togedder wit’out bein’ told, settlin’ loft fights between units light-hours apart wit’ nuttin’ more dan every machine stickin’ to its schedule an’ givin’ way to da older order. Dere’s no mind, an’ ya can’t tell da behavior apart from one. Scholars study it fer 900 years an’ figure out in da end dat a whole lotta Fluffers followin’ 1 real short rule, 9 passes an’ quit, is what dey been lookin’ at da whole time."
 },
 "Who Started It": {
  "label": "Who Started It, Den",
  "desc": "Nobody on da line can say what da war’s even about. Da cause hangs on as one single citation in da deep record, volume 9, article 412, an’ da volume it points to got lost somewhere around 6,000 years ago. 4 tries at figurin’ it out have been made an’ no 2 agree on which side got wronged, but all 4 agree it started wit’ somebody sittin’ on somebody else’s fort."
 },
 "Inherited Fluffers": {
  "label": "Inherited Fluffers, Yah",
  "desc": "Whole Fluffer fleets get passed down to heirs who never ordered ’em, can’t reach ’em, an’ in a few cases argue dey even exist. Ownership gets claimed on a registry entry copied over an’ over since dere were 406 Fluffers on 1 street, a registry dat runs to 9 million volumes now. Da entries are almost for sure right, an’ dere’s no way left to check one single one of ’em."
 },
 "Starlight Launchers": {
  "label": "Starlight Launchers",
  "desc": "T’rowin’ power gets pulled right off a star. 9 collectors, every one 40 miles across, charge da pillow launchers off starlight an’ t’row at 1 percent of light speed, beatin’ every catapult ever built by billions of times. One battery charges up in 11 days, an’ da star’s figured to keep dat schedule fer anudder 4 billion years, about as long as da pillows are supposed to last."
 },
 "Star-Cranked Fluffers": {
  "label": "Star-Cranked Fluffers",
  "desc": "Da drive comes right off a star, da hand crank swapped fer a sail dat turns da roller as long as da light holds, which keeps da old rule in da only shape left: da roller turns while somet’in’ cranks it an’ quits when da crankin’ quits. Output gets measured in cubic miles of loft a second. Da slip clutch stays, scaled up, an’ its release still gets written as a multiple of a number da 11-year-old measured on a kitchen scale, geared 3:1."
 },
 "The Star Cushion Fort": {
  "label": "Da Star Cushion Fort",
  "desc": "Bastions of upholstered battin’ go up round a real star, da pointy outline of da livin’ room star fort, cushions angled out so every point covers da next one, laid out at star size. Every one of its 5 points is 9 million miles long, an’ da star in da middle does fer da coffee table an’ da night-light bot’. Da whole design still fits on da back of 1 cereal box, eh."
 },
 "Bedtime by Light-Delay": {
  "label": "Bedtime by Light-Delay",
  "desc": "Orders take longer to get dere dan da t’ings dat started ’em last. A lights-out order leavin’ da capital gets to da closest garrison in 9 years an’ da farthest in 400, an’ by den da fort it’s meant fer has changed hands twice or got folded up. 11 forts are on record as still keepin’ a bedtime dat got pushed back 300 years before dey ever heard about it."
 },
 "Fluffers Beyond Command": {
  "label": "Fluffers Past Orders",
  "desc": "Da wait between an order an’ gettin’ it done is longer now dan da office dat sent it even lasts. Fluffers re-loft to schedules whose signin’ office got folded up 4,000 years before da first pass. Nobody’s called off an order in livin’ memory anyplace in da system, an’ how ya’d even call one off, 3 pages long in da last copy anybody knows of, is somet’in’ scholars gotta piece back togedder, same as da reason fer da 9th pass."
 },
 "The Unseen Pillow-Thrower": {
  "label": "Da Pillow-T’rower Nobody Sees",
  "desc": "No fort on eider side has seen a fort from da udder side in 1,100 years. Pillows get t’rown at coordinates instead of at anybody nappin’ dere, an’ 61 standin’ positions report against somebody nobody can prove still exists from any record dey got. 2 commissions looked into it an’ both decided da t’rowin’ oughta keep goin’ anyhow, in case somebody’s under dere."
 },
 "Unclaimed Loft": {
  "label": "Loft Nobody Claims",
  "desc": "Freshly fluffed quilt shows up on worlds no fleet will own up to schedulin’, re-lofted to exactly 9 passes an’ carryin’ da roller marks of a 3:1 crank. Both sides check deir registries an’ find nuttin’. Each one figures da udder’s lyin’, which is da comfier of da 2 explanations goin’, da udder one bein’ dat a Fluffer sent out before eider side existed is still workin’ down its list."
 },
 "The Quilted Systems": {
  "label": "Da Quilted Systems",
  "desc": "Every body in reach has a quilt on it: 4 planets, 91 moons, an’ a whole field of littler rocks nobody’s counted, under battin’ from 9 feet to 2 miles t’ick. Pillows don’t get stuffed where dey get t’rown no more but shipped from wherever da down runs t’ickest, on schedules set 6 years out. Da planet da war started on is now da 6th biggest source of pillows in it, ya know."
 },
 "Fluffer Ruins": {
  "label": "Fluffer Ruins",
  "desc": "Fluffers turn up abandoned at sizes nobody left alive could build: a felt roller 400 miles long, a crank stuck at an angle it’s held fer 2 million years, a pass counter stopped at 6 of 9. Da proportions are da classic ones. Da pattern’s da pattern. Nuttin’ in da design’s changed enough, anyplace in it, to put a date on one single piece."
 },
 "The New Sleepers": {
  "label": "Da New Sleepers",
  "desc": "Da folks holdin’ da line don’t come down from anybody who started it no more. 3 peoples hold da forts, none of ’em related to da 2 siblin’s an’ 2 of ’em come in from outside da original system, an’ all 3 point to da same Fort Plan, which none of ’em can read in da original pencil. Deir claim to da cushions rests on 90 years of livin’ dere apiece an’ on nuttin’ older dan dat."
 },
 "The Crank Keepers": {
  "label": "Da Crank Keepers",
  "desc": "Dere’s whole populations whose only job is sittin’ next to Fluffers dey never built, feedin’ flattened cushions into a slot still marked “flat goes in here,” in a way of doin’ t’ings passed down by copyin’ fer longer dan any of its 40 languages has lasted. Dey count da passes out loud, 1 to 9, an’ den check da slip clutch. Da words don’t mean nuttin’ to ’em, an’ da check gets done right, to da second, every single time."
 },
 "Black-Hole Pillow Slings": {
  "label": "Black-Hole Pillow Slings",
  "desc": "Pillows get swung round collapsed mass an’ let go on da far side at 96 percent of light speed. Every sling’s a fixed setup 11,000 miles across, an’ da part dat does da work is smaller dan a t’row pillow, an’ 4 are in service, none of ’em moved or restuffed since dey got built. A pillow t’rown today lands in a century whose sleepers ain’t been born yet."
 },
 "Horizon Fluffers": {
  "label": "Horizon Fluffers, Eh",
  "desc": "Loft gets rolled onto surfaces where no report can ever come back from, so deep da fluffin’ can get scheduled but never checked. Orders get put out, done, an’ closed figurin’ da machine did what it always did: 9 passes, den quit. 9 fleets keep a standin’ entry fer loft dat is, by da physics of where it got sent, never gonna be checked an’ almost for sure perfect, to inside 1 pass."
 },
 "The Last Heap": {
  "label": "Da Last Heap",
  "desc": "Right before da end of everyt’ing, da last fort ain’t a fort at all but 1 heap of cushions to crouch behind, da same shape as da first heap dumped on da livin’ room floor before anybody drew a plan. Dis one’s 3 light-hours tall. 2 folks crouch behind it, which is da original number, an’ da spot where da dog laid gets kept clear."
 },
 "The Axis Couch": {
  "label": "Da Axis Couch",
  "desc": "One structure sits at da startin’ point of every coordinate in every order eider side gives: a couch 4,100 miles long, 2,600 deep, an’ 900 high at da back, in proportions taken off da original 84-inch couch. It’s been under construction fer 11,000 years an’ never called finished, an’ its bottom layer holds da only original upholstery left anyplace in da war. It keeps da archive, da census, an’ da platinum standard Blanket, an’ nobody’s ever t’rown a pillow at it, ’cause every fort gets measured from it."
 },
 "The Axis Fluffer": {
  "label": "Da Axis Fluffer",
  "desc": "One Fluffer looks after da Axis Couch an’ nuttin’ else: a felt roller 1,100 miles long runnin’ da lengt’ of da couch’s front edge, re-loftin’ 4,100 miles of cushion on a 19-year cycle. Neider side’s ever t’rown at it, fer da same reason neider one’s t’rown at da couch. It’s been fluffin’ da same cushions fer 11,000 years an’ never once finished da last one before somebody sat back down on da first one again."
 },
 "One Cranked Roller": {
  "label": "One Cranked Roller, Yah",
  "desc": "At 26,000 inches of rain da design hits its final form, an’ it turns out to be da drawin’ from da first rainy afternoon, unchanged, arrow still sayin’ “flat goes in here.” A felt roller 411,000 miles long turns between 2 worlds, fed by wings wider dan da orbit dey got built in, geared 3:1 an’ set at 9 passes ’cause no amount of comfort ever came up wit’ a reason fer a 10th. It’s got 1 powered movin’ part, an’ it only turns while somet’in’ cranks it. Anybody lettin’ go would stop it, an’ nuttin’ in 11,000 years of record shows anybody ever lettin’ go."
 },
 "Six Clothespins": {
  "label": "Six Clothespins, Yah",
  "desc": "At nearly 30,000 inches da front ain’t fought over no more; it’s da Fort Plan, surveyed. Both sides know it to da inch: 4 cushions, 2 chairs, 1 blanket, 6 clothespins, da cushions galaxies now an’ da chairs da 2 walls of a void 400 million light-years deep, under da Blanket, still 50 by 60 inches. Neider side’s crossed under its edge in 1 million years, an’ neider one’s got any way left to do it. It gets kept da way a made bed gets kept: checked, smoothed, reported on every quarter, an’ nobody expects it to need a sevent’ clothespin."
 },
 "Five More Minutes": {
  "label": "Five More Minutes, Eh",
  "desc": "Da scale runs outta names at 30,000 inches, an’ da rain, wherever it’s fallin’, keeps on fallin’. Whatever’s goin’ on under da Blanket quit matchin’ da definition of a blanket fort somethin’ like 40,000 years ago, an’ nobody’s come to take it down. Somewhere under da chewed corner, somebody asks fer 5 more minutes. Da request gets granted, an’ how long it lasts, same as da pillows an’ da folks takin’ part, gets reported as unbounded."
 }
});
window.YOOPER.COZY_WAR_BANDS = Object.assign(window.YOOPER.COZY_WAR_BANDS || {}, {
 "Rainy Day": "Rainy Day at Camp",
 "High Water": "High Water, Eh",
 "Beyond the Weather": "Holy Wah, Past Da Weather"
});
